function rememberLidPhonePair(sessionId, first, second, source = 'message_key') {
    const left = String(first || '').trim();
    const right = String(second || '').trim();
    const leftIsLid = /@lid$/i.test(normalizeLidCacheKey(left));
    const rightIsLid = /@lid$/i.test(normalizeLidCacheKey(right));
    const leftPhone = normalizePhoneCacheJid(left);
    const rightPhone = normalizePhoneCacheJid(right);
    let lid = '';
    let phone = '';
    if (leftIsLid && rightPhone) {
        lid = normalizeLidCacheKey(left);
        phone = rightPhone;
    } else if (rightIsLid && leftPhone) {
        lid = normalizeLidCacheKey(right);
        phone = leftPhone;
    }
    if (!sessionId || !lid || !phone) return false;
    const sessionKey = `${sessionId}:${lid}`;
    const currentSessionRecord = lidPhoneResolutionCache.get(sessionKey);
    const trustedSessionSources = new Set(['signal_lid_mapping', 'signal_pn_lid_mapping', 'lid_mapping_update', 'message_key', 'cached_group_metadata', 'authenticated_own_identity']);
    const trustedSessionEvidence = trustedSessionSources.has(source);
    const sessionConflict = !!(currentSessionRecord?.phone && currentSessionRecord.phone !== phone);
    if (sessionConflict && !trustedSessionEvidence) {
        console.warn('[lid-phone-map-session-conflict]', {
            sessionId,
            lid,
            existingPhone: currentSessionRecord.phone,
            observedPhone: phone,
            source,
            action: 'keep_session_mapping'
        });
        return false;
    }
    const now = Date.now();
    const record = { phone, source, updatedAt: now };
    if (sessionConflict) {
        console.warn('[lid-phone-map-session-refresh]', {
            sessionId,
            lid,
            previousPhone: currentSessionRecord.phone,
            observedPhone: phone,
            source,
            action: 'replace_session_mapping_from_current_signal_evidence'
        });
    }
    lidPhoneResolutionCache.set(sessionKey, record);
    while (lidPhoneResolutionCache.size > 10000) lidPhoneResolutionCache.delete(lidPhoneResolutionCache.keys().next().value);
    const persistKey = `${sessionId}:${lid}`;
    const lastPersistedAt = Number(lidPhonePersistedKeys.get(persistKey) || 0);
    const mappingChanged = !currentSessionRecord?.phone || normalizePhoneCacheJid(currentSessionRecord.phone) !== phone;
    if (db && (mappingChanged || Date.now() - lastPersistedAt >= 12 * 60 * 60 * 1000) && !lidPhonePersistingKeys.has(persistKey)) {
        lidPhonePersistingKeys.add(persistKey);
        void (async () => {
            const collection = db.collection('lid_phone_mappings');
            const scopedId = `${sessionId}:${lid}`;
            await collection.updateOne(
                { _id: scopedId },
                { $set: { phone, lastSessionId: sessionId, sessionId, source, updatedAt: new Date(), expireAt: new Date(Date.now() + LID_PHONE_MAPPING_RETENTION_MS) }, $setOnInsert: { createdAt: new Date(), scoped: true } },
                { upsert: true }
            );
            lidPhonePersistedKeys.set(persistKey, Date.now());
            while (lidPhonePersistedKeys.size > 5000) lidPhonePersistedKeys.delete(lidPhonePersistedKeys.keys().next().value);
        })().catch(error => {
            console.warn('[lid-phone-map-persist-failed]', { sessionId, lid, error: error?.message || String(error) });
        }).finally(() => {
            lidPhonePersistingKeys.delete(persistKey);
        });
    }
    return true;
}

function getRememberedPhoneForLid(sessionId, lidValue) {
    const lid = normalizeLidCacheKey(lidValue);
    if (!lid || !/@lid$/i.test(lid)) return '';
    if (!sessionId) return '';
    const keys = [`${sessionId}:${lid}`];
    for (const key of keys) {
        const record = lidPhoneResolutionCache.get(key);
        if (!record) continue;
        if (Date.now() - record.updatedAt > LID_PHONE_MAPPING_RETENTION_MS) {
            lidPhoneResolutionCache.delete(key);
            continue;
        }
        const phone = normalizePhoneCacheJid(record.phone);
        if (phone) return phone;
    }
    return '';
}

function getRememberedLidForPhone(sessionId, phoneValue) {
    const phone = normalizePhoneCacheJid(phoneValue);
    if (!phone) return '';
    const now = Date.now();
    const sessionPrefix = sessionId ? `${sessionId}:` : '';
    const collect = prefix => {
        const matches = [];
        for (const [key, record] of lidPhoneResolutionCache.entries()) {
            if (!key.startsWith(prefix)) continue;
            if (normalizePhoneCacheJid(record?.phone) !== phone) continue;
            if (now - Number(record?.updatedAt || 0) > LID_PHONE_MAPPING_RETENTION_MS) {
                lidPhoneResolutionCache.delete(key);
                continue;
            }
            const lid = normalizeLidCacheKey(key.slice(prefix.length));
            if (/@lid$/i.test(lid)) matches.push({ lid, updatedAt: Number(record.updatedAt || 0) });
        }
        matches.sort((a, b) => b.updatedAt - a.updatedAt);
        return matches[0]?.lid || '';
    };
    if (!sessionPrefix) return '';
    return collect(sessionPrefix);
}

function phoneFromCachedGroupMetadata(sessionId, lidValue) {
    const lid = normalizeLidCacheKey(lidValue);
    if (!lid || !/@lid$/i.test(lid)) return null;
    const sessionPrefix = `${String(sessionId || '')}:`;
    for (const [cacheKey, cached] of groupMetadataCache.entries()) {
        if (!cacheKey.startsWith(sessionPrefix)) continue;
        const groupJid = cacheKey.slice(sessionPrefix.length);
        const participants = cached?.data?.participants;
        if (!Array.isArray(participants)) continue;
        for (const participant of participants) {
            const ids = [participant?.id, participant?.lid, participant?.idAlt, participant?.participantAlt, participant?.participantPn, participant?.jid].map(value => String(value || '').trim()).filter(Boolean);
            if (!ids.some(value => normalizeLidCacheKey(value) === lid)) continue;
            const phones = [participant?.phoneNumber, participant?.phone, participant?.pn, participant?.participantPn, participant?.idAlt, participant?.participantAlt, participant?.jid];
            const phone = phones.map(normalizePhoneCacheJid).find(Boolean);
            if (!phone) continue;
            rememberLidPhonePair(sessionId, lid, phone, 'cached_group_metadata');
            return { phone, source: 'cached_group_metadata', groupJid };
        }
    }
    return null;
}

function promiseWithTimeout(promise, timeoutMs, label = 'operation') {
    let timeoutHandle = null;
    const timeoutPromise = new Promise((_, reject) => {
        timeoutHandle = setTimeout(() => reject(new Error(`${label} timed out after ${timeoutMs}ms`)), timeoutMs);
    });
    return Promise.race([Promise.resolve(promise), timeoutPromise]).finally(() => {
        if (timeoutHandle) clearTimeout(timeoutHandle);
    });
}

function groupMetadataCacheKey(sessionId, groupJid) {
    const session = String(sessionId || '').trim();
    const group = String(groupJid || '').trim();
    return session && group ? `${session}:${group}` : '';
}

function getCachedGroupMetadata(sessionId, groupJid, maxAgeMs = GROUP_METADATA_CACHE_TTL_MS) {
    const key = groupMetadataCacheKey(sessionId, groupJid);
    if (!key) return null;
    const cached = groupMetadataCache.get(key);
    if (!cached?.data) return null;
    if (Date.now() - Number(cached.ts || 0) > maxAgeMs) {
        groupMetadataCache.delete(key);
        return null;
    }
    return cached.data;
}

function setCachedGroupMetadata(sessionId, groupJid, metadata) {
    const key = groupMetadataCacheKey(sessionId, groupJid);
    if (!key || !metadata || typeof metadata !== 'object') return false;
    groupMetadataCache.set(key, { data: metadata, ts: Date.now() });
    while (groupMetadataCache.size > 5000) groupMetadataCache.delete(groupMetadataCache.keys().next().value);
    return true;
}

function rememberGroupParticipantMappings(sessionId, metadata) {
    let saved = 0;
    for (const participant of Array.isArray(metadata?.participants) ? metadata.participants : []) {
        const identities = [participant?.id, participant?.lid, participant?.idAlt, participant?.participantAlt, participant?.participantPn, participant?.senderPn, participant?.jid, participant?.phoneNumber, participant?.phone, participant?.pn].map(value => String(value || '').trim()).filter(Boolean);
        const lids = [...new Set(identities.map(normalizeLidCacheKey).filter(value => /@lid$/i.test(value)))];
        const phones = [...new Set(identities.map(normalizePhoneCacheJid).filter(Boolean))];
        for (const lid of lids) {
            for (const phone of phones) {
                if (rememberLidPhonePair(sessionId, lid, phone, 'cached_group_metadata')) saved++;
            }
        }
    }
    return saved;
}

function invalidateCachedGroupMetadata(sessionId, groupJid) {
    const key = groupMetadataCacheKey(sessionId, groupJid);
    if (!key) return false;
    return groupMetadataCache.delete(key);
}

async function getGroupMetadataCached(sessionId, sock, groupJid, forceRefresh = false) {
    const group = String(groupJid || '').trim();
    if (!group || !/@g\.us$/i.test(group) || !sock?.groupMetadata) return null;
    if (forceRefresh) {
        try {
            const metadata = await promiseWithTimeout(sock.groupMetadata(group), GROUP_METADATA_FETCH_TIMEOUT_MS, 'WhatsApp group metadata lookup');
            if (metadata) {
                setCachedGroupMetadata(sessionId, group, metadata);
                rememberGroupParticipantMappings(sessionId, metadata);
            }
            return metadata || null;
        } catch (error) {
            console.warn('[group-metadata-refresh-failed]', { sessionId, groupJid: group, error: error?.message || String(error) });
            return null;
        }
    }
    const cached = getCachedGroupMetadata(sessionId, group);
    if (cached) {
        rememberGroupParticipantMappings(sessionId, cached);
        return cached;
    }
    const key = groupMetadataCacheKey(sessionId, group);
    const pending = groupMetadataFetchPromises.get(key);
    if (pending) return pending;
    const fetchPromise = (async () => {
        const metadata = await promiseWithTimeout(sock.groupMetadata(group), GROUP_METADATA_FETCH_TIMEOUT_MS, 'WhatsApp group metadata lookup');
        if (metadata) {
            setCachedGroupMetadata(sessionId, group, metadata);
            rememberGroupParticipantMappings(sessionId, metadata);
        }
        return metadata || null;
    })();
    groupMetadataFetchPromises.set(key, fetchPromise);
    try {
        return await fetchPromise;
    } catch (error) {
        console.warn('[group-metadata-lazy-fetch-failed]', { sessionId, groupJid: group, error: error?.message || String(error) });
        return null;
    } finally {
        if (groupMetadataFetchPromises.get(key) === fetchPromise) groupMetadataFetchPromises.delete(key);
    }
}

async function flushAuthWritesForSession(sessionId, timeoutMs = 30000) {
    const key = String(sessionId || '');
    const boundedTimeoutMs = Math.max(1000, Math.min(120000, Number(timeoutMs) || 30000));
    const deadline = Date.now() + boundedTimeoutMs;
    let drained = 0;
    while (Date.now() < deadline) {
        const pending = authWriteQueues.get(key);
        if (!pending) {
            const previousFailureState = authWriteFailures.get(key);
            const previousFailure = previousFailureState?.failures?.[0] || (typeof previousFailureState?.retry === 'function' ? previousFailureState : null);
            if (previousFailure) {
                const attempts = Number(previousFailure.attempts || 0);
                if (typeof previousFailure.retry !== 'function') throw new Error(`signal_auth_store_previous_write_failed:${previousFailure.message || 'unknown'}`);
                previousFailure.attempts = attempts + 1;
                const remaining = deadline - Date.now();
                if (remaining <= 0) break;
                try {
                    await promiseWithTimeout(previousFailure.retry(), Math.min(20000, remaining), 'Signal auth-store failed-write recovery');
                    drained++;
                    continue;
                } catch (retryError) {
                    const latestFailureState = authWriteFailures.get(key);
                    const latestFailure = latestFailureState?.failures?.find(item => item.id === previousFailure.id) || latestFailureState?.failures?.[0] || latestFailureState;
                    throw new Error(`signal_auth_store_previous_write_retry_failed:${latestFailure?.message || retryError?.message || 'unknown'}`);
                }
            }
            if (!drained) return;
            const activityAt = Number(authWriteActivityAt.get(key) || 0);
            if (!activityAt || Date.now() - activityAt >= 100) return;
            await new Promise(resolve => setTimeout(resolve, 100));
            continue;
        }
        const remaining = deadline - Date.now();
        if (remaining <= 0) break;
        try {
            await promiseWithTimeout(pending, Math.min(20000, remaining), 'Signal auth-store flush');
        } catch (error) {
            const failureState = authWriteFailures.get(key);
            if (!failureState) authWriteFailures.set(key, { message: String(error?.message || error).slice(0, 240), failures: [] });
            else failureState.message = String(error?.message || error).slice(0, 240);
            const timedOut = /timed out|timeout/i.test(String(error?.message || error));
            if (!timedOut && authWriteQueues.get(key) === pending) authWriteQueues.delete(key);
            throw error;
        }
        drained++;
        if (authWriteQueues.get(key) === pending) authWriteQueues.delete(key);
        const previousFailure = authWriteFailures.get(key);
        if (previousFailure) throw new Error(`signal_auth_store_previous_write_failed:${previousFailure.message || 'unknown'}`);
    }
    throw new Error('signal_auth_store_queue_did_not_quiesce');
}

async function waitForAuthStoreQuiescence(sessionId, timeoutMs = 45000, quietMs = 4500) {
    const key = String(sessionId || '');
    const boundedTimeoutMs = Math.max(1000, Math.min(60000, Number(timeoutMs) || 45000));
    const boundedQuietMs = Math.max(250, Math.min(10000, Number(quietMs) || 4500));
    const startedAt = Date.now();
    let lastError = null;
    while (Date.now() - startedAt < boundedTimeoutMs) {
        const remainingMs = boundedTimeoutMs - (Date.now() - startedAt);
        try {
            await flushAuthWritesForSession(key, Math.min(8000, Math.max(1000, remainingMs)));
            lastError = null;
        } catch (error) {
            lastError = error;
        }
        const runtimeAuthState = activeSessions.get(key)?.authState || null;
        const signalState = typeof runtimeAuthState?.getSignalTransactionState === 'function' ? runtimeAuthState.getSignalTransactionState() : { pendingCount: 0, oldestAgeMs: 0, lastActivityAt: 0 };
        const activityAt = Math.max(Number(authWriteActivityAt.get(key) || startedAt), Number(signalState.lastActivityAt || 0));
        if (!authWriteQueues.has(key) && Number(signalState.pendingCount || 0) === 0 && !lastError && Date.now() - activityAt >= boundedQuietMs) {
            await new Promise(resolve => setTimeout(resolve, 300));
            const finalSignalState = typeof runtimeAuthState?.getSignalTransactionState === 'function' ? runtimeAuthState.getSignalTransactionState() : { pendingCount: 0, lastActivityAt: 0 };
            const finalActivityAt = Math.max(Number(authWriteActivityAt.get(key) || startedAt), Number(finalSignalState.lastActivityAt || 0));
            if (!authWriteQueues.has(key) && Number(finalSignalState.pendingCount || 0) === 0 && finalActivityAt === activityAt) return true;
        }
        await new Promise(resolve => setTimeout(resolve, 250));
    }
    if (lastError) throw lastError;
    const runtimeAuthState = activeSessions.get(key)?.authState || null;
    const signalState = typeof runtimeAuthState?.getSignalTransactionState === 'function' ? runtimeAuthState.getSignalTransactionState() : { pendingCount: 0, oldestAgeMs: 0 };
    if (Number(signalState.pendingCount || 0) > 0) throw new Error(`signal_auth_transaction_queue_not_quiescent:${signalState.pendingCount}:${signalState.oldestAgeMs || 0}`);
    throw new Error('signal_auth_store_drain_timeout');
}

function attachTfbotSignalLidMappingAdapter(sessionId, sock) {
    const repository = sock?.signalRepository;
    const scopedSessionId = String(sessionId || '').trim();
    if (!repository || typeof repository !== 'object' || !scopedSessionId) {
        console.warn('[signal-lid-mapping-adapter-unavailable]', { sessionId: scopedSessionId || null, repositoryAvailable: !!repository });
        return false;
    }
    const existingAdapter = repository.lidMapping;
    if (existingAdapter?.__tfbotSessionScopedAdapter === true && existingAdapter.__tfbotSessionId === scopedSessionId) return true;
    const nativeMapping = existingAdapter && existingAdapter.__tfbotSessionScopedAdapter !== true ? existingAdapter : null;
    const validPhone = value => normalizePhoneCacheJid(value);
    const validLid = value => {
        const normalized = normalizeLidCacheKey(value);
        return /@lid$/i.test(normalized) ? normalized : '';
    };
    const readNative = async (method, value) => {
        if (typeof nativeMapping?.[method] !== 'function') return '';
        try {
            return await promiseWithTimeout(Promise.resolve().then(() => nativeMapping[method].call(nativeMapping, value)), 2000, 'native Signal LID mapping lookup');
        } catch (error) {
            console.warn('[signal-lid-native-mapping-read-failed]', { sessionId: scopedSessionId, method, errorName: error?.name || 'Error' });
            return '';
        }
    };
    const readDatabasePhone = async lid => {
        if (!db) return '';
        try {
            const record = await promiseWithTimeout(db.collection('lid_phone_mappings').findOne({ _id: `${scopedSessionId}:${lid}`, sessionId: scopedSessionId }, { projection: { phone: 1, source: 1 } }), 2000, 'session-scoped LID-to-PN adapter lookup');
            const phone = validPhone(record?.phone || '');
            if (phone) rememberLidPhonePair(scopedSessionId, lid, phone, record?.source || 'mongo_session_lid_phone_mapping');
            return phone;
        } catch (error) {
            console.warn('[signal-lid-mapping-database-read-failed]', { sessionId: scopedSessionId, direction: 'lid_to_pn', errorName: error?.name || 'Error', errorMessage: String(error?.message || error).slice(0, 180) });
            return '';
        }
    };
    const readDatabaseLid = async phone => {
        if (!db) return '';
        try {
            const record = await promiseWithTimeout(db.collection('lid_phone_mappings').findOne({ sessionId: scopedSessionId, phone }, { projection: { _id: 1, phone: 1 }, sort: { updatedAt: -1 } }), 2000, 'session-scoped PN-to-LID adapter lookup');
            const prefix = `${scopedSessionId}:`;
            const id = String(record?._id || '');
            return id.startsWith(prefix) ? validLid(id.slice(prefix.length)) : '';
        } catch (error) {
            console.warn('[signal-lid-mapping-database-read-failed]', { sessionId: scopedSessionId, direction: 'pn_to_lid', errorName: error?.name || 'Error', errorMessage: String(error?.message || error).slice(0, 180) });
            return '';
        }
    };
    const adapter = Object.create(nativeMapping && typeof nativeMapping === 'object' ? nativeMapping : null);
    Object.defineProperties(adapter, {
        __tfbotSessionScopedAdapter: { value: true, enumerable: false },
        __tfbotSessionId: { value: scopedSessionId, enumerable: false }
    });
    adapter.getPNForLID = async (rawLid, rawGroupJid = '') => {
        const lid = validLid(rawLid);
        if (!lid) return '';
        const nativePhone = validPhone(await readNative('getPNForLID', lid));
        if (nativePhone) {
            rememberLidPhonePair(scopedSessionId, lid, nativePhone, 'signal_lid_mapping');
            return nativePhone;
        }
        const runtime = activeSessions.get(scopedSessionId);
        const credentials = runtime?.authState?.creds || {};
        const ownLid = validLid(getAuthenticatedLid(sock.user || null, credentials) || runtime?.ownLidJid || '');
        const ownPhoneNumber = getAuthenticatedPhoneNumber(sock.user || null, credentials) || normalizedJidNumber(runtime?.ownPhoneJid || '');
        const ownPhone = validPhone(ownPhoneNumber ? `${ownPhoneNumber}@s.whatsapp.net` : runtime?.ownPhoneJid || '');
        if (ownLid && ownLid === lid && ownPhone) {
            rememberLidPhonePair(scopedSessionId, lid, ownPhone, 'authenticated_own_identity');
            return ownPhone;
        }
        const cached = validPhone(getRememberedPhoneForLid(scopedSessionId, lid));
        if (cached) return cached;
        const groupMapping = phoneFromCachedGroupMetadata(scopedSessionId, lid);
        if (groupMapping?.phone) return validPhone(groupMapping.phone);
        return await readDatabasePhone(lid);
    };
    adapter.getLIDForPN = async rawPhone => {
        const phone = validPhone(rawPhone);
        if (!phone) return '';
        const nativeLid = validLid(await readNative('getLIDForPN', phone));
        if (nativeLid) {
            rememberLidPhonePair(scopedSessionId, nativeLid, phone, 'signal_pn_lid_mapping');
            return nativeLid;
        }
        const cached = validLid(getRememberedLidForPhone(scopedSessionId, phone));
        if (cached) return cached;
        return await readDatabaseLid(phone);
    };
    adapter.storeLIDPNMappings = async entries => {
        const rows = entries instanceof Map
            ? [...entries.entries()].map(([lid, pn]) => ({ lid, pn }))
            : Array.isArray(entries)
                ? entries
                : entries && typeof entries === 'object'
                    ? Object.entries(entries).map(([lid, pn]) => ({ lid, pn }))
                    : [];
        let saved = 0;
        for (const row of rows) {
            const lid = validLid(row?.lid || row?.LID || row?.lidJid || row?.lidJID || row?.from || '');
            const phone = validPhone(row?.pn || row?.PN || row?.phoneNumber || row?.phone || row?.pnJid || row?.to || '');
            if (!lid || !phone) continue;
            rememberLidPhonePair(scopedSessionId, lid, phone, 'signal_lid_mapping');
            if (db) {
                await promiseWithTimeout(db.collection('lid_phone_mappings').updateOne(
                    { _id: `${scopedSessionId}:${lid}` },
                    { $set: { phone, lastSessionId: scopedSessionId, sessionId: scopedSessionId, source: 'signal_lid_mapping', updatedAt: new Date(), expireAt: new Date(Date.now() + LID_PHONE_MAPPING_RETENTION_MS) }, $setOnInsert: { createdAt: new Date(), scoped: true } },
                    { upsert: true }
                ), 2000, 'persist session-scoped LID/PN mapping');
                lidPhonePersistedKeys.set(`${scopedSessionId}:${lid}`, Date.now());
            }
            saved++;
        }
        if (typeof nativeMapping?.storeLIDPNMappings === 'function') {
            try { await nativeMapping.storeLIDPNMappings.call(nativeMapping, rows); }
            catch (error) { console.warn('[signal-lid-native-mapping-write-failed]', { sessionId: scopedSessionId, errorName: error?.name || 'Error' }); }
        }
        return saved;
    };
    try {
        repository.lidMapping = adapter;
        if (repository.lidMapping !== adapter) Object.defineProperty(repository, 'lidMapping', { configurable: true, enumerable: true, writable: true, value: adapter });
        const attached = repository.lidMapping === adapter && typeof repository.lidMapping.getPNForLID === 'function' && typeof repository.lidMapping.getLIDForPN === 'function';
        console.info(attached ? '[signal-lid-mapping-adapter-attached]' : '[signal-lid-mapping-adapter-attach-failed]', {
            sessionId: scopedSessionId,
            nativeProvider: !!nativeMapping,
            mongoFallback: !!db,
            cacheFallback: true,
            mappingScope: 'session_scoped',
            getPNForLID: typeof repository.lidMapping?.getPNForLID === 'function',
            getLIDForPN: typeof repository.lidMapping?.getLIDForPN === 'function'
        });
        return attached;
    } catch (error) {
        console.warn('[signal-lid-mapping-adapter-attach-failed]', { sessionId: scopedSessionId, errorName: error?.name || 'Error', errorMessage: String(error?.message || error).slice(0, 180) });
        return false;
    }
}

async function resolvePhoneForLid(sessionId, sock, lidValue) {
    const lid = normalizeLidCacheKey(lidValue);
    if (!lid || !/@lid$/i.test(lid)) return null;
    const cached = getRememberedPhoneForLid(sessionId, lid);
    const sessionRecord = lidPhoneResolutionCache.get(`${sessionId}:${lid}`);
    if (cached && sessionRecord && Date.now() - Number(sessionRecord.updatedAt || 0) <= LID_PHONE_MAPPING_FRESH_MS) {
        return { phone: cached, source: sessionRecord.source || 'session_lid_phone_cache' };
    }
    try {
        const mapped = normalizePhoneCacheJid(await promiseWithTimeout(sock?.signalRepository?.lidMapping?.getPNForLID?.(lid), 2000, 'LID-to-PN socket lookup'));
        if (mapped) {
            rememberLidPhonePair(sessionId, lid, mapped, 'signal_lid_mapping');
            return { phone: mapped, source: 'signal_lid_mapping' };
        }
    } catch (error) {
        console.warn('[lid-phone-socket-resolution-failed]', { sessionId, lid, error: error?.message || String(error) });
    }
    if (cached) return { phone: cached, source: sessionRecord?.source || 'session_lid_phone_cache' };
    const groupMetadataResolution = phoneFromCachedGroupMetadata(sessionId, lid);
    if (groupMetadataResolution?.phone) return groupMetadataResolution;
    if (db) {
        try {
            const scopedRecord = await promiseWithTimeout(db.collection('lid_phone_mappings').findOne({ _id: `${sessionId}:${lid}`, sessionId }, { projection: { phone: 1, source: 1 } }), 2000, 'session-scoped LID-to-PN database lookup');
            const persistedPhone = normalizePhoneCacheJid(scopedRecord?.phone || '');
            if (persistedPhone) {
                rememberLidPhonePair(sessionId, lid, persistedPhone, scopedRecord?.source || 'mongo_session_lid_phone_mapping');
                return { phone: persistedPhone, source: 'mongo_session_lid_phone_mapping' };
            }
        } catch (error) {
            console.warn('[lid-phone-database-resolution-failed]', { sessionId, lid, error: error?.message || String(error) });
        }
    }
    return null;
}

function schedulePhoneResolutionForLid(sessionId, sock, lidValue, source = 'background_lid_lookup') {
    const lid = normalizeLidCacheKey(lidValue);
    if (!sessionId || !lid || !/@lid$/i.test(lid)) return Promise.resolve('');
    const cached = normalizePhoneCacheJid(getRememberedPhoneForLid(sessionId, lid));
    const record = lidPhoneResolutionCache.get(`${sessionId}:${lid}`);
    if (cached && record && Date.now() - Number(record.updatedAt || 0) <= LID_PHONE_MAPPING_FRESH_MS) return Promise.resolve(cached);
    const key = `${sessionId}:${lid}`;
    const existing = lidPhoneLookupInFlight.get(key);
    if (existing) return existing;
    const lookup = promiseWithTimeout(
        Promise.resolve().then(() => sock?.signalRepository?.lidMapping?.getPNForLID?.(lid)),
        2000,
        'background LID-to-PN lookup'
    ).then(value => {
        const phone = normalizePhoneCacheJid(value);
        if (phone) rememberLidPhonePair(sessionId, lid, phone, 'signal_lid_mapping');
        return phone;
    }).catch(error => {
        console.info('[lid-phone-background-resolution-unavailable]', { sessionId, lidHash: shortLogHash(lid), source, errorName: error?.name || 'Error' });
        return '';
    }).finally(() => {
        if (lidPhoneLookupInFlight.get(key) === lookup) lidPhoneLookupInFlight.delete(key);
    });
    lidPhoneLookupInFlight.set(key, lookup);
    return lookup;
}

async function resolveLidForPhone(sessionId, sock, phoneValue) {
    const phone = normalizePhoneCacheJid(phoneValue);
    if (!phone) return null;
    const remembered = getRememberedLidForPhone(sessionId, phone);
    const sessionRecord = remembered ? lidPhoneResolutionCache.get(`${sessionId}:${remembered}`) : null;
    if (remembered && sessionRecord && Date.now() - Number(sessionRecord.updatedAt || 0) <= LID_PHONE_MAPPING_FRESH_MS) {
        return { lid: remembered, source: sessionRecord.source || 'session_phone_lid_cache' };
    }
    try {
        const mappedLid = normalizeLidCacheKey(await promiseWithTimeout(sock?.signalRepository?.lidMapping?.getLIDForPN?.(phone), 1500, 'PN-to-LID socket lookup'));
        if (/@lid$/i.test(mappedLid)) {
            rememberLidPhonePair(sessionId, mappedLid, phone, 'signal_pn_lid_mapping');
            return { lid: mappedLid, source: 'signal_pn_lid_mapping' };
        }
    } catch (error) {
        console.warn('[pn-lid-socket-resolution-failed]', { sessionId, phone, error: error?.message || String(error) });
    }
    return /@lid$/i.test(remembered) ? { lid: remembered, source: 'session_lid_cache' } : null;
}

async function refreshAuthenticatedSessionOwnIdentity(sessionId, sock, credentials, source = 'connection_update') {
    if (!sessionId || !sock) return null;
    const currentRuntime = activeSessions.get(sessionId);
    if (currentRuntime?.sock !== sock) return null;
    const existing = ownIdentityRefreshPromises.get(sessionId);
    if (existing?.sock === sock && existing.promise) return existing.promise;
    const refreshPromise = (async () => {
        const creds = credentials || currentRuntime?.authState?.creds || {};
        let phone = getAuthenticatedPhoneNumber(sock.user || null, creds) || normalizedJidNumber(currentRuntime?.ownPhoneJid || '');
        let phoneJid = phone ? normalizePhoneCacheJid(`${phone}@s.whatsapp.net`) : normalizePhoneCacheJid(currentRuntime?.ownPhoneJid || '');
        let lid = normalizeLidCacheKey(getAuthenticatedLid(sock.user || null, creds) || currentRuntime?.ownLidJid || getRememberedLidForPhone(sessionId, phoneJid));
        let identitySource = 'authenticated_credentials';
        if (phoneJid && !/@lid$/i.test(lid)) {
            const mapped = await resolveLidForPhone(sessionId, sock, phoneJid).catch(() => null);
            if (mapped?.lid) {
                lid = normalizeLidCacheKey(mapped.lid);
                identitySource = mapped.source || 'pn_to_lid_mapping';
            }
        }
        if ((!phoneJid || !/^\d{6,20}@s\.whatsapp\.net$/i.test(phoneJid)) && /@lid$/i.test(lid)) {
            try {
                phoneJid = normalizePhoneCacheJid(await promiseWithTimeout(sock.signalRepository?.lidMapping?.getPNForLID?.(lid), 2000, 'Own LID-to-PN lookup'));
                if (phoneJid) {
                    phone = phoneJid.split('@')[0];
                    identitySource = 'lid_to_pn_mapping';
                }
            } catch (error) {
                console.warn('[session-own-lid-pn-resolution-failed]', { sessionId, source, error: error?.message || String(error) });
            }
        }
        const ownLidJid = /@lid$/i.test(lid) ? lid : '';
        if (phoneJid && ownLidJid) rememberLidPhonePair(sessionId, ownLidJid, phoneJid, 'authenticated_own_identity');
        const liveRuntime = activeSessions.get(sessionId);
        if (liveRuntime?.sock === sock) {
            liveRuntime.ownPhoneJid = phoneJid || liveRuntime.ownPhoneJid || '';
            liveRuntime.ownLidJid = ownLidJid || liveRuntime.ownLidJid || '';
            liveRuntime.ownIdentityUpdatedAt = Date.now();
        }
        console.info('[session-own-identity-refreshed]', { sessionId, source, identitySource, phoneAvailable: !!phoneJid, lidAvailable: !!ownLidJid, mappingPersistQueued: !!(phoneJid && ownLidJid) });
        return { phoneJid, lidJid: ownLidJid, source: identitySource };
    })();
    ownIdentityRefreshPromises.set(sessionId, { sock, promise: refreshPromise });
    try {
        return await refreshPromise;
    } finally {
        if (ownIdentityRefreshPromises.get(sessionId)?.promise === refreshPromise) ownIdentityRefreshPromises.delete(sessionId);
    }
}

function cacheMessageIdentityAliases(sessionId, message) {
    const key = message?.key || {};
    const pairs = [];
    if (key.remoteJid && key.remoteJidAlt) pairs.push([key.remoteJid, key.remoteJidAlt]);
    if (!key.fromMe) {
        if (key.remoteJid && key.senderPn) pairs.push([key.remoteJid, key.senderPn]);
        if (key.remoteJid && key.participantPn) pairs.push([key.remoteJid, key.participantPn]);
    }
    if (key.participant && key.participantAlt) pairs.push([key.participant, key.participantAlt]);
    if (key.participant && key.participantPn) pairs.push([key.participant, key.participantPn]);
    if (!key.fromMe && key.participant && key.senderPn) pairs.push([key.participant, key.senderPn]);
    let saved = 0;
    for (const [first, second] of pairs) if (rememberLidPhonePair(sessionId, first, second)) saved++;
    return saved;
}

function getMessageQueue(queueKey, partitionKey = '') {
    if (!queueKey || (typeof queueKey !== 'object' && typeof queueKey !== 'function')) return fallbackMessageQueue;
    let queues = messageQueues.get(queueKey);
    if (!queues) {
        queues = new Map();
        messageQueues.set(queueKey, queues);
    }
    const key = String(partitionKey || '__session__');
    let queue = queues.get(key);
    if (!queue) {
        queue = { tasks: [], isSendingQueue: false, blockedOperation: null, partitionKey: key, socket: queueKey };
        queues.set(key, queue);
    } else if (!queue.socket && queueKey && typeof queueKey === 'object') {
        queue.socket = queueKey;
    }
    return queue;
}

function createQueueSocketCloseWaiter(sock) {
    const listeners = [];
    let settled = false;
    let resolveWait;
    const promise = new Promise(resolve => { resolveWait = resolve; });
    const removeListeners = () => {
        for (const item of listeners.splice(0)) {
            try {
                if (typeof item.target.off === 'function') item.target.off(item.event, item.listener);
                else if (typeof item.target.removeListener === 'function') item.target.removeListener(item.event, item.listener);
            } catch (error) {}
        }
    };
    const finish = closed => {
        if (settled) return;
        settled = true;
        removeListeners();
        resolveWait(!!closed);
    };
    if (sock?.ws && typeof sock.ws.on === 'function') {
        const closeListener = () => finish(true);
        sock.ws.on('close', closeListener);
        listeners.push({ target: sock.ws, event: 'close', listener: closeListener });
    }
    if (sock?.ev && typeof sock.ev.on === 'function') {
        const updateListener = update => {
            if (String(update?.connection || '').toLowerCase() === 'close') finish(true);
        };
        sock.ev.on('connection.update', updateListener);
        listeners.push({ target: sock.ev, event: 'connection.update', listener: updateListener });
    }
    const readyState = sock?.ws?.readyState ?? sock?.ws?._socket?.readyState ?? sock?.socket?.readyState;
    if (Number(readyState) === 3 || String(readyState).toUpperCase() === 'CLOSED' || sock?.ws?.isOpen === false) finish(true);
    return { promise, cancel: () => finish(false) };
}

async function processMessageQueue(queue) {
    if (queue.isSendingQueue || queue.blockedOperation) return;
    queue.isSendingQueue = true;
    try {
        while (queue.tasks.length > 0 && !queue.blockedOperation) {
            const task = queue.tasks.shift();
            const startedAt = Date.now();
            const operation = Promise.resolve().then(() => task.execute());
            const socketCloseWaiter = createQueueSocketCloseWaiter(queue.socket);
            let outcome;
            try {
                outcome = await Promise.race([
                    promiseWithTimeout(operation, Number(task.timeoutMs) > 0 ? task.timeoutMs : MESSAGE_QUEUE_TASK_TIMEOUT_MS, 'WhatsApp queued operation').then(
                        result => ({ type: 'resolved', result }),
                        error => ({ type: /timed out/i.test(String(error?.message || error)) ? 'timeout' : 'rejected', error })
                    ),
                    socketCloseWaiter.promise.then(closed => ({ type: closed ? 'socket_closed' : 'cancelled' }))
                ]);
            } finally {
                socketCloseWaiter.cancel();
            }
            if (outcome.type === 'resolved') {
                task.resolve(outcome.result);
            } else if (outcome.type === 'timeout') {
                queue.blockedOperation = operation;
                const lateSocketCloseWaiter = createQueueSocketCloseWaiter(queue.socket);
                let lateReleaseTimer = setTimeout(() => {
                    if (queue.blockedOperation !== operation) return;
                    queue.blockedOperation = null;
                    console.warn('[message-queue-slow-operation-isolated]', { taskId: task.id, partition: queue.partitionKey || '__session__', durationMs: Date.now() - startedAt, thresholdMs: MESSAGE_QUEUE_TASK_TIMEOUT_MS, graceMs: Number(task.lateGraceMs) > 0 ? task.lateGraceMs : MESSAGE_QUEUE_LATE_GRACE_MS, callerStillWaitingForActualResult: true, nextTaskReleased: true, lateOperationMayStillSettle: true });
                    if (queue.tasks.length) setImmediate(() => processMessageQueue(queue));
                }, Number(task.lateGraceMs) > 0 ? task.lateGraceMs : MESSAGE_QUEUE_LATE_GRACE_MS);
                if (typeof lateReleaseTimer.unref === 'function') lateReleaseTimer.unref();
                const clearBlockedOperation = result => {
                    if (queue.blockedOperation !== operation) return false;
                    clearTimeout(lateReleaseTimer);
                    queue.blockedOperation = null;
                    if (queue.tasks.length) setImmediate(() => processMessageQueue(queue));
                    return true;
                };
                operation.then(
                    result => {
                        task.resolve(result);
                        lateSocketCloseWaiter.cancel();
                        const released = clearBlockedOperation();
                        console.warn('[message-queue-late-operation-settled]', { taskId: task.id, partition: queue.partitionKey || '__session__', durationMs: Date.now() - startedAt, result: 'resolved', queueWasReleasedEarlier: !released, nextTaskReleased: true });
                    },
                    lateError => {
                        task.reject(lateError);
                        lateSocketCloseWaiter.cancel();
                        const released = clearBlockedOperation();
                        console.warn('[message-queue-late-operation-settled]', { taskId: task.id, partition: queue.partitionKey || '__session__', durationMs: Date.now() - startedAt, result: 'rejected', error: lateError?.message || String(lateError), queueWasReleasedEarlier: !released, nextTaskReleased: true });
                    }
                );
                lateSocketCloseWaiter.promise.then(closed => {
                    if (!closed) return;
                    task.reject(new Error('whatsapp_socket_closed_during_late_queued_operation'));
                    if (clearBlockedOperation()) console.warn('[message-queue-late-operation-cancelled-by-socket-close]', { taskId: task.id, partition: queue.partitionKey || '__session__', durationMs: Date.now() - startedAt, action: 'release_destination_queue_and_reject_old_socket_operation' });
                });
                console.warn('[message-queue-task-slow]', {
                    taskId: task.id,
                    durationMs: Date.now() - startedAt,
                    thresholdMs: Number(task.timeoutMs) > 0 ? task.timeoutMs : MESSAGE_QUEUE_TASK_TIMEOUT_MS,
                    remainingTasks: queue.tasks.length,
                    partition: queue.partitionKey || '__session__',
                    action: 'keep_caller_pending_until_actual_send_result_and_release_only_this_destination_after_grace'
                });
                break;
            } else if (outcome.type === 'socket_closed') {
                task.reject(new Error('whatsapp_socket_closed_during_queued_operation'));
                console.warn('[message-queue-operation-interrupted-by-socket-close]', {
                    taskId: task.id,
                    partition: queue.partitionKey || '__session__',
                    durationMs: Date.now() - startedAt,
                    action: 'reject_old_socket_task_without_force_closing_or_restarting_other_partitions'
                });
            } else {
                task.reject(outcome.error || new Error('whatsapp_queued_operation_failed'));
                console.warn('[message-queue-task-failed]', {
                    taskId: task.id,
                    durationMs: Date.now() - startedAt,
                    partition: queue.partitionKey || '__session__',
                    error: outcome.error?.message || String(outcome.error || 'queued_operation_cancelled')
                });
            }
            const delay = Number.isFinite(task.delay) ? Math.max(0, task.delay) : 0;
            if (delay > 0) await new Promise(resolve => setTimeout(resolve, delay));
        }
    } finally {
        queue.isSendingQueue = false;
        if (queue.tasks.length > 0 && !queue.blockedOperation) setImmediate(() => processMessageQueue(queue));
    }
}
function queueMessage(executeFn, delayMs = 150, queueKey = null, partitionKey = '', taskOptions = {}) {
    const queue = getMessageQueue(queueKey, partitionKey);
    return new Promise((resolve, reject) => {
        if (queue.tasks.length >= 300) {
            const error = new Error('whatsapp_message_queue_overloaded');
            console.error('[message-queue-overloaded]', { pendingTasks: queue.tasks.length, partition: queue.partitionKey || '__session__', action: 'reject_new_task_to_prevent_unbounded_backlog' });
            reject(error);
            return;
        }
        queue.tasks.push({ id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, execute: executeFn, delay: delayMs, timeoutMs: Number(taskOptions.timeoutMs) || 0, lateGraceMs: Number(taskOptions.lateGraceMs) || 0, resolve, reject });
        void processMessageQueue(queue);
    });
}

async function claimMessageForProcessing(sessionId, messageId, remoteJid = '', accountIdentity = '', upsertType = 'notify') {
    if (!sessionId || !messageId) return false;
    if (!db) return true;
    const normalizedChat = String(remoteJid || 'unknown-chat').trim();
    const normalizedMessageId = String(messageId || '').trim();
    const accountScope = String(accountIdentity || sessionId).trim();
    const accountScopeHash = shortLogHash(accountScope);
    const documentId = `${accountScopeHash}:${normalizedMessageId}`;
    const now = Date.now();
    const leaseUntil = new Date(now + MESSAGE_PROCESSING_LEASE_MS);
    const reclaimConditions = [
        { status: { $exists: false } },
        { status: 'retryable' },
        { status: 'processing', leaseUntil: { $lte: new Date(now) } }
    ];
    const previousOwnerInstanceId = previousDeploymentSessionTakeoverOwners.get(sessionId);
    if (previousOwnerInstanceId) {
        const escapedOwnerId = previousOwnerInstanceId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        reclaimConditions.push({ status: 'processing', sessionId, claimOwner: { $regex: `^${escapedOwnerId}-` } });
    }
    try {
        const result = await db.collection('processed_messages').updateOne(
            { _id: documentId, $or: reclaimConditions },
            {
                $set: { sessionId, accountScopeHash, messageId: normalizedMessageId, remoteJid: normalizedChat, upsertType: String(upsertType || 'notify'), status: 'processing', claimOwner: processInstanceId, claimedAt: new Date(now), leaseUntil, ts: now, expireAt: new Date(now + PROCESSED_MESSAGE_RETENTION_MS) },
                $inc: { attempts: 1 }
            },
            { upsert: true, writeConcern: { w: 'majority', wtimeout: 10000 } }
        );
        return result.upsertedCount === 1 || result.matchedCount === 1;
    } catch (error) {
        if (error && error.code === 11000) return false;
        console.warn('[message-dedupe-persistent-claim-unavailable]', { sessionId, remoteJid: normalizedChat, messageId: normalizedMessageId, error: error?.message || String(error), action: 'continue_under_exclusive_session_runtime_lock_and_local_message_id_deduplication' });
        return true;
    }
}

async function renewMessageProcessingClaim(sessionId, messageId, accountIdentity = '') {
    if (!db || !sessionId || !messageId) return false;
    const accountScope = String(accountIdentity || sessionId).trim();
    const documentId = `${shortLogHash(accountScope)}:${String(messageId || '').trim()}`;
    const now = new Date();
    try {
        const result = await db.collection('processed_messages').updateOne(
            { _id: documentId, sessionId, status: 'processing', claimOwner: processInstanceId },
            { $set: { leaseUntil: new Date(now.getTime() + MESSAGE_PROCESSING_LEASE_MS), heartbeatAt: now, expireAt: new Date(now.getTime() + PROCESSED_MESSAGE_RETENTION_MS) } }
        );
        return result.matchedCount === 1;
    } catch (error) {
        console.warn('[message-processing-claim-heartbeat-failed]', { sessionId, messageId, error: error?.message || String(error) });
        return false;
    }
}

async function finishMessageProcessingClaim(sessionId, messageId, accountIdentity = '', succeeded = true, error = '') {
    if (!db || !sessionId || !messageId) return false;
    const normalizedMessageId = String(messageId || '').trim();
    const accountScope = String(accountIdentity || sessionId).trim();
    const documentId = `${shortLogHash(accountScope)}:${normalizedMessageId}`;
    const now = new Date();
    try {
        const update = succeeded
            ? { $set: { status: 'processed', processedAt: now, leaseUntil: now, expireAt: new Date(now.getTime() + PROCESSED_MESSAGE_RETENTION_MS) }, $unset: { claimOwner: 1, lastError: 1 } }
            : { $set: { status: 'retryable', leaseUntil: new Date(0), lastError: String(error || 'message_handler_failed').slice(0, 240), failedAt: now }, $unset: { claimOwner: 1 } };
        const result = await db.collection('processed_messages').updateOne({ _id: documentId, status: 'processing', claimOwner: processInstanceId }, update, { writeConcern: { w: 'majority', wtimeout: 10000 } });
        if (result.matchedCount !== 1) return false;
        console.info('[message-processing-claim-finalized]', { sessionId, messageId: normalizedMessageId, status: succeeded ? 'processed' : 'retryable' });
        return true;
    } catch (finishError) {
        console.warn('[message-processing-claim-finalize-failed]', { sessionId, messageId: normalizedMessageId, status: succeeded ? 'processed' : 'retryable', error: finishError?.message || String(finishError) });
        return false;
    }
}

function normalizeOutgoingRetryAlias(value) {
    const phoneJid = normalizePhoneCacheJid(value);
    if (phoneJid) return phoneJid;
    const lidJid = normalizeLidCacheKey(value);
    return /@lid$/i.test(lidJid) ? lidJid : '';
}

function getOutgoingRetryAliasMemoryKey(sessionId, alias, messageId) {
    const normalizedAlias = normalizeOutgoingRetryAlias(alias);
    const id = String(messageId || '').trim();
    return sessionId && normalizedAlias && id ? `${sessionId}|${normalizedAlias}|${id}` : '';
}

function buildOutgoingRetryLookupKeys(sessionId, messageId, aliases = []) {
    const id = String(messageId || '').trim();
    if (!sessionId || !id) return [];
    const keys = [`${sessionId}|id|${id}`];
    const phoneAliases = new Set();
    const lidAliases = new Set();
    for (const value of Array.isArray(aliases) ? aliases : []) {
        const normalized = normalizeOutgoingRetryAlias(value);
        if (!normalized) continue;
        if (/@s\.whatsapp\.net$/i.test(normalized)) phoneAliases.add(normalized);
        else if (/@lid$/i.test(normalized)) lidAliases.add(normalized);
    }
    for (const phone of phoneAliases) keys.push(`${sessionId}|pn|${phone}|${id}`);
    for (const lid of lidAliases) keys.push(`${sessionId}|lid|${lid}|${id}`);
    return [...new Set(keys)];
}

function removeOutgoingRetryMessageMemory(cacheKey, removeAliases = false) {
    const entry = outgoingRetryMessageMemory.get(cacheKey);
    if (!entry) return false;
    if (removeAliases) {
        for (const alias of Array.isArray(entry.lookupAliases) ? entry.lookupAliases : []) {
            const aliasKey = getOutgoingRetryAliasMemoryKey(entry.sessionId, alias, entry.messageId);
            if (aliasKey) outgoingRetryAliasMemory.delete(aliasKey);
        }
    }
    outgoingRetryMessageMemory.delete(cacheKey);
    return true;
}

function cacheOutgoingRetryMessageMemory(sessionId, message, extraAliases = []) {
    const messageId = String(message?.key?.id || '').trim();
    if (!sessionId || !messageId || !message?.message || message?.key?.fromMe === false) return false;
    const cacheKey = `${sessionId}:${messageId}`;
    const aliases = [...new Set([message?.key?.remoteJid, message?.key?.remoteJidAlt, message?.key?.participant, message?.key?.participantAlt, message?.key?.participantPn, message?.key?.senderPn, ...(Array.isArray(extraAliases) ? extraAliases : [])].map(value => String(value || '').trim()).filter(Boolean))].slice(0, 32);
    const lookupAliases = [...new Set(aliases.map(normalizeOutgoingRetryAlias).filter(Boolean))];
    removeOutgoingRetryMessageMemory(cacheKey, true);
    const entry = { sessionId, messageId, key: { ...(message.key || {}), fromMe: true }, aliases, lookupAliases, message: message.message, cachedAt: Date.now() };
    outgoingRetryMessageMemory.set(cacheKey, entry);
    for (const alias of lookupAliases) {
        const aliasKey = getOutgoingRetryAliasMemoryKey(sessionId, alias, messageId);
        if (aliasKey) outgoingRetryAliasMemory.set(aliasKey, entry);
    }
    const now = Date.now();
    for (const [key, value] of outgoingRetryMessageMemory) {
        if (now - Number(value?.cachedAt || 0) > OUTGOING_RETRY_MEMORY_TTL_MS) removeOutgoingRetryMessageMemory(key);
        else if (outgoingRetryMessageMemory.size <= OUTGOING_RETRY_MEMORY_MAX_ENTRIES) break;
    }
    while (outgoingRetryMessageMemory.size > OUTGOING_RETRY_MEMORY_MAX_ENTRIES) removeOutgoingRetryMessageMemory(outgoingRetryMessageMemory.keys().next().value);
    for (const [aliasKey, aliasEntry] of outgoingRetryAliasMemory) {
        if (now - Number(aliasEntry?.cachedAt || 0) > OUTGOING_RETRY_MEMORY_TTL_MS) outgoingRetryAliasMemory.delete(aliasKey);
    }
    const aliasLimit = OUTGOING_RETRY_MEMORY_MAX_ENTRIES * 12;
    while (outgoingRetryAliasMemory.size > aliasLimit) outgoingRetryAliasMemory.delete(outgoingRetryAliasMemory.keys().next().value);
    return true;
}

function getOutgoingRetryMessageMemory(sessionId, messageId, requestedAliases = []) {
    const normalizedSessionId = String(sessionId || '');
    const normalizedMessageId = String(messageId || '').trim();
    const cacheKey = `${normalizedSessionId}:${normalizedMessageId}`;
    const now = Date.now();
    let entry = outgoingRetryMessageMemory.get(cacheKey);
    let lookupMode = 'message_id';
    if (entry && now - Number(entry.cachedAt || 0) > OUTGOING_RETRY_MEMORY_TTL_MS) {
        removeOutgoingRetryMessageMemory(cacheKey);
        entry = null;
    }
    if (!entry) {
        for (const alias of Array.isArray(requestedAliases) ? requestedAliases : []) {
            const aliasKey = getOutgoingRetryAliasMemoryKey(normalizedSessionId, alias, normalizedMessageId);
            const indexedEntry = aliasKey ? outgoingRetryAliasMemory.get(aliasKey) : null;
            if (indexedEntry && indexedEntry.sessionId === normalizedSessionId && indexedEntry.messageId === normalizedMessageId && now - Number(indexedEntry.cachedAt || 0) <= OUTGOING_RETRY_MEMORY_TTL_MS) {
                entry = indexedEntry;
                lookupMode = /@lid$/i.test(normalizeOutgoingRetryAlias(alias)) ? 'lid_alias' : 'pn_alias';
                break;
            }
            if (aliasKey && indexedEntry) outgoingRetryAliasMemory.delete(aliasKey);
        }
    }
    if (!entry) return null;
    return { ...entry, lookupMode };
}

function cacheRecentMessage(sessionId, message, extraAliases = []) {
    const id = message?.key?.id;
    if (!sessionId || !id || !message?.message) return;
    const entry = {
        sessionId,
        id,
        key: message.key ? { ...message.key } : null,
        from: message.key.remoteJid || '',
        chatAliases: [...new Set([message.key.remoteJid, message.key.remoteJidAlt, message.key.participant, message.key.participantAlt, message.key.participantPn, message.key.senderPn, ...(Array.isArray(extraAliases) ? extraAliases : [])].map(value => String(value || '').trim()).filter(Boolean))],
        sender: message.key.participant || message.key.remoteJid || '',
        fromMe: !!message.key.fromMe,
        participantAlt: message.key.participantAlt || message.key.participantPn || '',
        ts: Number(message.messageTimestamp) || Math.floor(Date.now() / 1000),
        message: message.message
    };
    const now = Date.now();
    for (let index = recentMsgsCache.length - 1; index >= 0; index--) {
        const cached = recentMsgsCache[index];
        const cachedAt = Number(cached?.cachedAt || 0);
        if (!cachedAt || now - cachedAt > RECENT_MESSAGE_MEMORY_TTL_MS) recentMsgsCache.splice(index, 1);
    }
    entry.cachedAt = now;
    const existingIndex = recentMsgsCache.findIndex(item => item.sessionId === sessionId && item.id === id);
    if (existingIndex >= 0) recentMsgsCache.splice(existingIndex, 1);
    recentMsgsCache.push(entry);
    if (entry.fromMe) cacheOutgoingRetryMessageMemory(sessionId, message, entry.chatAliases);
    if (recentMsgsCache.length > 1000) recentMsgsCache.splice(0, recentMsgsCache.length - 1000);
    persistQuotedMessageForCommands(sessionId, message, entry.chatAliases);
}

function persistQuotedMessageForCommands(sessionId, message, aliases = []) {
    try {
        if (!db || !sessionId || !message?.key?.id || !message?.message) return;
        const key = message.key || {};
        const remoteJid = String(key.remoteJid || key.remoteJidAlt || '').trim();
        if (!remoteJid) return;
        const groupMessage = /@g\.us$/i.test(remoteJid) || /@g\.us$/i.test(String(key.remoteJidAlt || ''));
        const mediaInfo = extractWhatsAppResendMedia(message);
        const mediaMessage = !!mediaInfo;
        if (!groupMessage && !mediaMessage) return;
        const messageId = String(key.id);
        const now = Date.now();
        const timestampValue = message.messageTimestamp && typeof message.messageTimestamp.toNumber === 'function'
            ? message.messageTimestamp.toNumber()
            : Number(message.messageTimestamp || 0);
        const messageFormat = getWhatsAppMessageFormat(message);
        const retainMediaPayload = mediaMessage && (mediaInfo.viewOnce === true || key.fromMe !== true);
        const record = {
            _id: `quoted:${sessionId}:${messageId}`,
            sessionId,
            messageId,
            remoteJid,
            remoteJidAlt: String(key.remoteJidAlt || ''),
            remoteJidAliases: [...new Set([remoteJid, key.remoteJidAlt, key.participant, key.participantAlt, key.participantPn, key.senderPn, ...(Array.isArray(aliases) ? aliases : [])].map(value => String(value || '').trim()).filter(Boolean))].slice(0, 16),
            fromMe: key.fromMe === true,
            participant: String(key.participant || ''),
            participantAlt: String(key.participantAlt || ''),
            participantPn: String(key.participantPn || ''),
            senderPn: String(key.senderPn || ''),
            key: { ...key },
            messageFormat,
            message: retainMediaPayload ? message.message : null,
            messageTimestamp: Number.isFinite(timestampValue) && timestampValue > 0 ? timestampValue : Math.floor(now / 1000),
            createdAt: new Date(now),
            expireAt: new Date(now + 7 * 24 * 60 * 60 * 1000)
        };
        void db.collection('baileys_quoted_messages').updateOne(
            { _id: record._id },
            { $set: record },
            { upsert: true }
        ).catch(error => {
            if (!serverShuttingDown) console.warn('[quoted-message-cache-persist-failed]', { sessionId, messageId, groupMessage, mediaMessage, error: error?.message || String(error) });
        });
    } catch (error) {
        if (!serverShuttingDown) console.warn('[quoted-message-cache-prepare-failed]', { sessionId, error: error?.message || String(error) });
    }
}

async function persistOutgoingRetryMessage(sessionId, jid, message, jidAliases = [], accountPhone = '', accountJid = '', accountLid = '', persistenceMode = 'background_without_blocking_message_dispatch') {
    if (!db || !sessionId || !message?.key?.id || !message?.message) {
        console.warn('[message-retry-store-write-skipped]', { sessionId: sessionId || null, messageId: message?.key?.id || null, databaseAvailable: !!db, messageComplete: !!(message?.key?.id && message?.message), persistenceMode });
        return false;
    }
    const messageId = String(message.key.id);
    const remoteJid = String(message.key.remoteJid || jid || '');
    const remoteJidAlt = String(message.key.remoteJidAlt || '');
    const remoteJidAliases = [...new Set([remoteJid, remoteJidAlt, jid, message?.key?.participant, message?.key?.participantAlt, message?.key?.participantPn, message?.key?.senderPn, ...(Array.isArray(jidAliases) ? jidAliases : [])].map(value => String(value || '').trim()).filter(Boolean))].slice(0, 32);
    const accountPhoneJid = normalizePhoneCacheJid(accountPhone) || normalizePhoneCacheJid(`${normalizePhoneNumber(accountPhone)}@s.whatsapp.net`);
    const accountLidJid = normalizeLidCacheKey(accountLid || '');
    const phoneAliases = [...new Set(remoteJidAliases.map(normalizePhoneCacheJid).filter(Boolean))];
    const lidAliases = [...new Set(remoteJidAliases.map(normalizeLidCacheKey).filter(value => /@lid$/i.test(value)))];
    const destinationAliases = [...new Set([message?.key?.remoteJid, message?.key?.remoteJidAlt, jid].map(value => String(value || '').trim()).filter(Boolean))];
    const destinationPhoneAliases = destinationAliases.map(normalizePhoneCacheJid).filter(Boolean);
    const destinationLidAliases = destinationAliases.map(normalizeLidCacheKey).filter(value => /@lid$/i.test(value));
    const isSelfChatRetry = !!((accountPhoneJid && destinationPhoneAliases.includes(accountPhoneJid)) || (/@lid$/i.test(accountLidJid) && destinationLidAliases.includes(accountLidJid)));
    const rememberedOwnLid = accountPhoneJid ? getRememberedLidForPhone(sessionId, accountPhoneJid) : '';
    const mappedLidAlias = accountPhoneJid ? lidAliases.find(value => getRememberedPhoneForLid(sessionId, value) === accountPhoneJid) || '' : '';
    const retryPhoneJid = isSelfChatRetry ? accountPhoneJid : '';
    const retryLidJid = isSelfChatRetry ? (/@lid$/i.test(accountLidJid) ? accountLidJid : rememberedOwnLid || mappedLidAlias || (/@lid$/i.test(normalizeLidCacheKey(remoteJidAlt)) ? normalizeLidCacheKey(remoteJidAlt) : '')) : '';
    const selfRetryAliases = isSelfChatRetry ? [retryPhoneJid, retryLidJid].filter(Boolean) : [];
    const retryLookupKeys = buildOutgoingRetryLookupKeys(sessionId, messageId, selfRetryAliases);
    const normalizedMessage = { ...message, key: { ...(message.key || {}), id: messageId, remoteJid, ...(remoteJidAlt ? { remoteJidAlt } : {}), fromMe: true } };
    cacheOutgoingRetryMessageMemory(sessionId, normalizedMessage, [...remoteJidAliases, ...selfRetryAliases]);
    const record = {
        _id: `${sessionId}:${messageId}`,
        sessionId,
        accountPhone: normalizePhoneNumber(accountPhone),
        accountJid: String(accountJid || ''),
        accountLid: accountLidJid,
        messageId,
        remoteJid,
        remoteJidAlt,
        remoteJidAliases,
        isSelfChatRetry,
        retryPhoneJid,
        retryLidJid,
        retryLookupKeys,
        messageKey: { id: messageId, remoteJid, remoteJidAlt, participant: String(message?.key?.participant || ''), participantAlt: String(message?.key?.participantAlt || ''), participantPn: String(message?.key?.participantPn || ''), senderPn: String(message?.key?.senderPn || ''), fromMe: true },
        fromMe: true,
        message: message.message,
        messageTimestamp: Number(message.messageTimestamp) || Math.floor(Date.now() / 1000),
        createdAt: new Date()
    };
    console.info('[message-retry-store-write-started]', { sessionId, messageId, destinationType: getWhatsAppDestinationType(remoteJid), messageType: Object.keys(message.message || {}).join(',') || 'unknown', aliasCount: remoteJidAliases.length, selfChatRetry: isSelfChatRetry, retryKeys: { messageId: true, pn: !!retryPhoneJid, lid: !!retryLidJid }, persistenceMode, durableWriteRequested: true });
    try {
        await promiseWithTimeout(db.collection('baileys_outgoing_messages').updateOne(
            { _id: record._id },
            { $set: record },
            { upsert: true, writeConcern: { w: 'majority', wtimeout: BAILEYS_RETRY_STORE_WRITE_TIMEOUT_MS } }
        ), BAILEYS_RETRY_STORE_WRITE_TIMEOUT_MS + 300, 'Baileys outgoing retry message persistence');
        console.info('[message-retry-store-write-completed]', { sessionId, messageId, remoteJid, aliasCount: remoteJidAliases.length, selfChatRetry: isSelfChatRetry, retryKeys: { messageId: true, pn: !!retryPhoneJid, lid: !!retryLidJid }, persistenceMode, durableWriteConcern: 'majority' });
        return true;
    } catch (error) {
        console.warn('[message-retry-store-write-failed]', { sessionId, messageId, destinationType: getWhatsAppDestinationType(remoteJid), messageType: Object.keys(message.message || {}).join(',') || 'unknown', persistenceMode, failureClass: classifyWhatsAppFailure(error), errorName: error?.name || error?.constructor?.name || null, error: String(error?.message || error).slice(0, 700) });
        return false;
    }
}

function normalizeEchoText(value) {
    return String(value || '').replace(/\r\n?/g, '\n').replace(/[ \t]+/g, ' ').replace(/\n{2,}/g, '\n').trim();
}

function normalizePersonName(value) {
    return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function normalizeConnectionFormat(value, fallback = 'pair') {
    const normalized = String(value || '').trim().toLowerCase();
    if (['qr', 'qrcode', 'qr-code', 'scan', 'scanqr'].includes(normalized)) return 'qr';
    if (['pair', 'paircode', 'pair-code', 'pairing', 'code'].includes(normalized)) return 'pair';
    return String(fallback || '').trim().toLowerCase() === 'qr' ? 'qr' : 'pair';
}

function normalizedJidNumber(value) {
    const raw = String(value || '').trim();
    if (!raw || /@lid$/i.test(raw) || /@(?:g\.us|newsletter|broadcast|s\.whatsapp\.net-status)$/i.test(raw)) return '';
    if (raw.includes('@') && !/@(?:s\.whatsapp\.net|c\.us)$/i.test(raw)) return '';
    return normalizePhoneNumber(raw.split('@')[0].split(':')[0]);
}

function getAuthenticatedPhoneNumber(user, creds) {
    const candidates = [user?.phoneNumber, user?.id, creds?.me?.id];
    for (const candidate of candidates) {
        const raw = String(candidate || '').trim();
        if (!raw || /@lid$/i.test(raw)) continue;
        if (raw.includes('@') && !/@(?:s\.whatsapp\.net|c\.us)$/i.test(raw)) continue;
        const number = normalizedJidNumber(raw);
        if (/^\d{6,20}$/.test(number)) return number;
    }
    return '';
}

function getAuthenticatedLid(user, creds) {
    const candidates = [user?.lid, creds?.me?.lid, /@lid$/i.test(String(creds?.me?.id || '').trim()) ? creds.me.id : '', /@lid$/i.test(String(user?.id || '').trim()) ? user.id : ''];
    for (const candidate of candidates) {
        const lid = normalizeLidCacheKey(candidate);
        if (/@lid$/i.test(lid)) return lid;
    }
    return '';
}

function normalizeOutgoingEchoJid(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    if (/@lid$/i.test(raw)) return normalizeLidCacheKey(raw);
    const phoneJid = normalizePhoneCacheJid(raw);
    if (phoneJid) return phoneJid;
    return raw.toLowerCase();
}

function areEquivalentWhatsAppChatJids(sessionId, first, second) {
    const left = String(first || '').trim();
    const right = String(second || '').trim();
    if (!left || !right) return false;
    if (normalizeOutgoingEchoJid(left) === normalizeOutgoingEchoJid(right)) return true;
    const leftPhone = normalizePhoneCacheJid(left) || getRememberedPhoneForLid(sessionId, left);
    const rightPhone = normalizePhoneCacheJid(right) || getRememberedPhoneForLid(sessionId, right);
    return !!leftPhone && !!rightPhone && leftPhone === rightPhone;
}


async function invalidateSenderKeyMemoryForParticipant(sessionId, participantJid, reason = 'identity_change', onlyGroupJid = '') {
    const normalizedParticipant = normalizeOutgoingEchoJid(participantJid);
    if (!sessionId || !normalizedParticipant || !db) return { scanned: 0, changed: 0, removed: 0 };
    const active = activeSessions.get(sessionId);
    const keyStore = active?.signalKeyStore || active?.sock?.authState?.keys;
    if (!keyStore || typeof keyStore.get !== 'function' || typeof keyStore.set !== 'function') return { scanned: 0, changed: 0, removed: 0 };
    const aliases = new Set([normalizedParticipant]);
    const participantPhone = normalizePhoneCacheJid(participantJid) || getRememberedPhoneForLid(sessionId, participantJid);
    const participantLid = /@lid$/i.test(normalizeLidCacheKey(participantJid)) ? normalizeLidCacheKey(participantJid) : getRememberedLidForPhone(sessionId, participantPhone);
    if (participantPhone) aliases.add(normalizeOutgoingEchoJid(participantPhone));
    if (/@lid$/i.test(participantLid)) aliases.add(normalizeOutgoingEchoJid(participantLid));
    const prefix = `auth-${sessionId}_key_sender-key-memory-`;
    const escapedPrefix = prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const groupIds = new Set();
    if (onlyGroupJid && /@g\.us$/i.test(String(onlyGroupJid))) {
        groupIds.add(String(onlyGroupJid));
    } else {
        try {
            const docs = await db.collection('baileys_auth').find(
                { _id: { $regex: `^${escapedPrefix}` } },
                { projection: { _id: 1 } }
            ).limit(2000).toArray();
            for (const doc of docs) {
                const groupJid = String(doc?._id || '').slice(prefix.length);
                if (/@g\.us$/i.test(groupJid)) groupIds.add(groupJid);
            }
        } catch (error) {
            console.warn('[sender-key-memory-enumeration-failed]', { sessionId, error: error?.message || String(error) });
        }
        const groupPrefix = `${sessionId}:`;
        for (const cacheKey of groupMetadataCache.keys()) {
            if (!cacheKey.startsWith(groupPrefix)) continue;
            const groupJid = cacheKey.slice(groupPrefix.length);
            if (/@g\.us$/i.test(groupJid)) groupIds.add(groupJid);
        }
    }
    let changedGroups = 0;
    let removedEntries = 0;
    let scannedGroups = 0;
    for (const groupJid of groupIds) {
        scannedGroups++;
        try {
            const stored = await promiseWithTimeout(keyStore.get('sender-key-memory', [groupJid]), 5000, 'Read group sender-key memory');
            const currentMap = stored?.[groupJid];
            if (!currentMap || typeof currentMap !== 'object' || Array.isArray(currentMap)) continue;
            const nextMap = { ...currentMap };
            let removedHere = 0;
            for (const storedJid of Object.keys(nextMap)) {
                const canonicalStored = normalizeOutgoingEchoJid(storedJid);
                const matches = aliases.has(canonicalStored) || [...aliases].some(alias => areEquivalentWhatsAppChatJids(sessionId, storedJid, alias));
                if (matches) {
                    delete nextMap[storedJid];
                    removedHere++;
                }
            }
            if (!removedHere) continue;
            const nextValue = Object.keys(nextMap).length ? nextMap : null;
            await promiseWithTimeout(keyStore.set({ 'sender-key-memory': { [groupJid]: nextValue } }), 8000, 'Invalidate changed participant sender-key memory');
            changedGroups++;
            removedEntries += removedHere;
        } catch (error) {
            console.warn('[sender-key-memory-participant-invalidation-failed]', { sessionId, groupJid, reason, error: error?.message || String(error) });
        }
    }
    if (changedGroups) console.info('[sender-key-memory-invalidation-persisted]', { sessionId, reason, changedGroups, removedEntries, persistence: 'key_store_set_confirmed' });
    console.info('[sender-key-memory-participant-invalidated]', {
        sessionId,
        participant: normalizedParticipant,
        reason,
        scannedGroups,
        changedGroups,
        removedEntries
    });
    return { scanned: scannedGroups, changed: changedGroups, removed: removedEntries };
}

async function resetSessionGroupSenderKeyMemory(sessionId, reason = 'group_membership_change', onlyGroupJid = '') {
    if (!sessionId || !db) return 0;
    const active = activeSessions.get(sessionId);
    const keyStore = active?.signalKeyStore || active?.sock?.authState?.keys;
    if (!keyStore || typeof keyStore.set !== 'function') return 0;
    const groupIds = new Set();
    const prefix = `auth-${sessionId}_key_sender-key-memory-`;
    const escapedPrefix = prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (onlyGroupJid && /@g\.us$/i.test(onlyGroupJid)) groupIds.add(onlyGroupJid);
    else {
        try {
            const docs = await db.collection('baileys_auth').find(
                { _id: { $regex: `^${escapedPrefix}` } },
                { projection: { _id: 1 } }
            ).limit(2000).toArray();
            for (const doc of docs) {
                const groupJid = String(doc?._id || '').slice(prefix.length);
                if (/@g\.us$/i.test(groupJid)) groupIds.add(groupJid);
            }
        } catch (error) {
            console.warn('[sender-key-memory-reset-enumeration-failed]', { sessionId, reason, error: error?.message || String(error) });
        }
        const groupPrefix = `${sessionId}:`;
        for (const cacheKey of groupMetadataCache.keys()) {
            if (!cacheKey.startsWith(groupPrefix)) continue;
            const groupJid = cacheKey.slice(groupPrefix.length);
            if (/@g\.us$/i.test(groupJid)) groupIds.add(groupJid);
        }
    }
    let resetCount = 0;
    for (const groupJid of groupIds) {
        try {
            await promiseWithTimeout(keyStore.set({ 'sender-key-memory': { [groupJid]: null } }), 8000, 'Reset group sender-key memory');
            setBoundedMapEntry(groupSenderKeyResetAt, `${sessionId}:${groupJid}`, Date.now(), 5000);
            resetCount++;
        } catch (error) {
            console.warn('[sender-key-memory-group-reset-failed]', { sessionId, groupJid, reason, error: error?.message || String(error) });
        }
    }
    console.info('[sender-key-memory-session-reset]', { sessionId, reason, resetCount, persistence: 'key_store_set_confirmed' });
    return resetCount;
}

async function resetGroupSenderKeyMemoryBeforeSend(sessionId, groupJid) {
    const normalizedGroupJid = String(groupJid || '').trim();
    if (!GROUP_SENDER_KEY_RESET_ON_SEND || !sessionId || !/@g\.us$/i.test(normalizedGroupJid)) return false;
    const cacheKey = `${sessionId}:${normalizedGroupJid}`;
    const lastResetAt = Number(groupSenderKeyResetAt.get(cacheKey) || 0);
    if (!GROUP_SENDER_KEY_RESET_EVERY_SEND && lastResetAt && Date.now() - lastResetAt < GROUP_SENDER_KEY_SEND_RESET_COOLDOWN_MS) {
        console.info('[group-sender-key-preparation-reused]', { sessionId, groupJid: normalizedGroupJid, cooldownRemainingMs: Math.max(0, GROUP_SENDER_KEY_SEND_RESET_COOLDOWN_MS - (Date.now() - lastResetAt)), action: 'reuse_sender_key_memory_after_recent_successful_preparation' });
        return true;
    }
    const pending = groupSenderKeyResetInFlight.get(cacheKey);
    if (pending) return pending;
    const active = activeSessions.get(sessionId);
    const keyStore = active?.signalKeyStore || active?.sock?.authState?.keys;
    if (!keyStore || typeof keyStore.set !== 'function') {
        console.warn('[group-sender-key-memory-reset-skipped]', { sessionId, groupJid: normalizedGroupJid, reason: 'signal_key_store_not_attached' });
        return false;
    }
    const operation = (async () => {
        try {
            await promiseWithTimeout(keyStore.set({ 'sender-key-memory': { [normalizedGroupJid]: null } }), 8000, 'Initial group sender-key memory reset');
            setBoundedMapEntry(groupSenderKeyResetAt, cacheKey, Date.now(), 5000);
            while (groupSenderKeyResetAt.size > 10000) groupSenderKeyResetAt.delete(groupSenderKeyResetAt.keys().next().value);
            console.info(GROUP_SENDER_KEY_RESET_EVERY_SEND ? '[group-sender-key-memory-reset-before-every-send]' : '[group-sender-key-memory-cooldown-reset]', {
                sessionId,
                groupJid: normalizedGroupJid,
                resetEverySend: GROUP_SENDER_KEY_RESET_EVERY_SEND,
                cooldownMs: GROUP_SENDER_KEY_RESET_EVERY_SEND ? 0 : GROUP_SENDER_KEY_SEND_RESET_COOLDOWN_MS,
                action: GROUP_SENDER_KEY_RESET_EVERY_SEND ? 'clear_sender_key_memory_before_each_group_send_to_reissue_distribution' : 'reset_once_per_group_cooldown'
            });
            return true;
        } catch (error) {
            console.warn('[group-sender-key-memory-reset-failed]', { sessionId, groupJid: normalizedGroupJid, error: error?.message || String(error) });
            return false;
        }
    })();
    groupSenderKeyResetInFlight.set(cacheKey, operation);
    try {
        return await operation;
    } finally {
        if (groupSenderKeyResetInFlight.get(cacheKey) === operation) groupSenderKeyResetInFlight.delete(cacheKey);
    }
}

function rememberOutgoingMessageId(sessionId, messageId) {
    const id = String(messageId || '').trim();
    if (!sessionId || !id) return;
    const now = Date.now();
    outgoingMessageIdCache.set(`${sessionId}:${id}`, now);
    for (const [key, timestamp] of outgoingMessageIdCache.entries()) {
        if (now - timestamp > OUTGOING_ECHO_TTL_MS) outgoingMessageIdCache.delete(key);
    }
    while (outgoingMessageIdCache.size > 5000) outgoingMessageIdCache.delete(outgoingMessageIdCache.keys().next().value);
}

function isRecentOutgoingMessageId(sessionId, messageId) {
    const key = `${sessionId}:${String(messageId || '').trim()}`;
    const timestamp = outgoingMessageIdCache.get(key);
    if (!timestamp) return false;
    if (Date.now() - timestamp > OUTGOING_ECHO_TTL_MS) {
        outgoingMessageIdCache.delete(key);
        return false;
    }
    return true;
}

function rememberOutgoingTextEcho(sessionId, jid, content) {
    const text = normalizeEchoText(content?.text || content?.caption || '');
    const canonicalJid = normalizeOutgoingEchoJid(jid);
    if (!sessionId || !canonicalJid || !text) return null;
    const createdAt = Date.now();
    const keys = [`${sessionId}:jid:${canonicalJid}:${text}`];
    for (const key of keys) outgoingTextEchoCache.set(key, createdAt);
    const cutoff = createdAt - OUTGOING_ECHO_TTL_MS;
    for (const [storedKey, timestamp] of outgoingTextEchoCache.entries()) {
        if (timestamp < cutoff) outgoingTextEchoCache.delete(storedKey);
    }
    while (outgoingTextEchoCache.size > 4000) outgoingTextEchoCache.delete(outgoingTextEchoCache.keys().next().value);
    return { keys, createdAt };
}

function consumeOutgoingTextEcho(sessionId, jid, text) {
    const normalized = normalizeEchoText(text);
    const canonicalJid = normalizeOutgoingEchoJid(jid);
    if (!sessionId || !canonicalJid || !normalized) return false;
    const candidateJids = new Set([canonicalJid]);
    if (/@lid$/i.test(canonicalJid)) {
        const phoneJid = normalizePhoneCacheJid(getRememberedPhoneForLid(sessionId, canonicalJid));
        if (phoneJid) candidateJids.add(phoneJid);
    } else if (/@s\.whatsapp\.net$/i.test(canonicalJid)) {
        const lidJid = normalizeLidCacheKey(getRememberedLidForPhone(sessionId, canonicalJid));
        if (/@lid$/i.test(lidJid)) candidateJids.add(lidJid);
    }
    const now = Date.now();
    for (const candidateJid of candidateJids) {
        const key = `${sessionId}:jid:${candidateJid}:${normalized}`;
        const timestamp = outgoingTextEchoCache.get(key);
        if (timestamp && now - timestamp <= OUTGOING_ECHO_TTL_MS) {
            outgoingTextEchoCache.delete(key);
            return true;
        }
        if (timestamp) outgoingTextEchoCache.delete(key);
    }
    return false;
}

function getSelfChatAddressPlan(originalDestinationJid, ownPhoneJid, ownLidJid) {
    const original = String(originalDestinationJid || '').trim();
    const originalLid = normalizeLidCacheKey(original);
    const originalPhone = normalizePhoneCacheJid(original);
    const ownPhone = normalizePhoneCacheJid(ownPhoneJid || '');
    const ownLid = normalizeLidCacheKey(ownLidJid || '');
    if (/@lid$/i.test(originalLid) && ownLid && originalLid === ownLid) {
        return { primaryJid: originalLid, fallbackJid: ownPhone, originalType: 'lid', primaryType: 'lid', fallbackType: ownPhone ? 'phone' : '' };
    }
    if (originalPhone && ownPhone && originalPhone === ownPhone) {
        return { primaryJid: originalPhone, fallbackJid: ownLid, originalType: 'phone', primaryType: 'phone', fallbackType: ownLid ? 'lid' : '' };
    }
    if (ownLid) {
        return { primaryJid: ownLid, fallbackJid: ownPhone, originalType: /@lid$/i.test(original) ? 'lid' : /@s\.whatsapp\.net$/i.test(original) ? 'phone' : 'unknown', primaryType: 'lid', fallbackType: ownPhone ? 'phone' : '' };
    }
    return { primaryJid: ownPhone, fallbackJid: '', originalType: /@lid$/i.test(original) ? 'lid' : /@s\.whatsapp\.net$/i.test(original) ? 'phone' : 'unknown', primaryType: 'phone', fallbackType: '' };
}

async function getAuthenticatedSelfPhoneJid(sessionId, sock, credentials) {
    const user = sock?.user || null;
    const ownLid = normalizeLidCacheKey(getAuthenticatedLid(user, credentials));
    if (ownLid) {
        try {
            const livePhone = normalizePhoneCacheJid(await promiseWithTimeout(sock?.signalRepository?.lidMapping?.getPNForLID?.(ownLid), 2000, 'Self PN lookup'));
            if (livePhone) {
                rememberLidPhonePair(sessionId, ownLid, livePhone, 'signal_lid_mapping');
                return livePhone;
            }
        } catch (error) {}
    }
    const number = getAuthenticatedPhoneNumber(user, credentials) || normalizePhoneNumber(user?.phoneNumber || '');
    return /^\d{6,20}$/.test(String(number || '')) ? normalizePhoneCacheJid(`${number}@s.whatsapp.net`) : '';
}

function getMessageQueuePartitionKey(sessionId, jid, session) {
    const destination = String(jid || '').trim();
    if (!destination) return '__unknown_chat__';
    const lower = destination.toLowerCase();
    if (/@g\.us$/i.test(destination)) return `group:${lower}`;
    if (/@newsletter$/i.test(destination)) return `channel:${lower}`;
    if (/^status@broadcast$/i.test(destination)) return 'broadcast:status';
    const credentials = session?.authState?.creds || session?.sock?.authState?.creds || null;
    const ownPhone = normalizePhoneCacheJid(`${getAuthenticatedPhoneNumber(session?.sock?.user, credentials) || ''}@s.whatsapp.net`);
    const ownLid = normalizeLidCacheKey(getAuthenticatedLid(session?.sock?.user, credentials));
    const destinationPhone = normalizePhoneCacheJid(destination) || getRememberedPhoneForLid(sessionId, destination);
    if (ownPhone && destinationPhone === ownPhone) return `private:${ownPhone}`;
    if (/@lid$/i.test(destination)) {
        const destinationLid = normalizeLidCacheKey(destination);
        if (ownPhone && ownLid && destinationLid === ownLid) return `private:${ownPhone}`;
        if (destinationPhone) return `private:${destinationPhone}`;
        return `private:${destinationLid}`;
    }
    if (destinationPhone) return `private:${destinationPhone}`;
    return `chat:${normalizeOutgoingEchoJid(destination)}`;
}

async function resetSignalPeerSessionForSendRetry(sock, sessionId, jid, allowOwnPeer = false) {
    const peerJid = String(jid || '').trim();
    if (!peerJid || /@(?:g\.us|newsletter|broadcast)$/i.test(peerJid)) return false;
    const runtime = activeSessions.get(sessionId);
    if (!runtime && !sock) return false;
    const now = Date.now();
    const ownCredentials = runtime?.authState?.creds || sock?.authState?.creds || null;
    const ownPhone = getAuthenticatedPhoneNumber(sock?.user || null, ownCredentials);
    const ownPhoneJid = normalizePhoneCacheJid(ownPhone ? `${ownPhone}@s.whatsapp.net` : '');
    const ownLidJid = normalizeLidCacheKey(getAuthenticatedLid(sock?.user || null, ownCredentials));
    const peerPhoneJid = normalizePhoneCacheJid(peerJid) || normalizePhoneCacheJid(getRememberedPhoneForLid(sessionId, peerJid));
    const isOwnPeer = !!((ownPhoneJid && peerPhoneJid && ownPhoneJid === peerPhoneJid) || (/@lid$/i.test(ownLidJid) && /@lid$/i.test(peerJid) && ownLidJid === normalizeLidCacheKey(peerJid)));
    if (isOwnPeer && !allowOwnPeer) return false;
    const repairKey = `${sessionId}:send-preserve:${isOwnPeer ? 'self' : shortLogHash(peerJid)}`;
    if (Number(signalPeerSendRepairCooldowns.get(repairKey) || 0) > now) return false;
    signalPeerSendRepairCooldowns.set(repairKey, now + 30000);
    while (signalPeerSendRepairCooldowns.size > 4000) signalPeerSendRepairCooldowns.delete(signalPeerSendRepairCooldowns.keys().next().value);
    await flushAuthWritesForSession(sessionId);
    console.warn('[signal-peer-session-preserved-for-send-retry]', {
        sessionId,
        peerHash: shortLogHash(peerJid),
        selfPeer: isOwnPeer,
        signalKeysDeleted: false,
        sessionMigrated: false,
        action: 'flush_pending_auth_writes_and_retry_without_deleting_or_migrating_signal_session'
    });
    return true;
}
async function reportTfbotWorkerSendFailure(sessionId, error) {
    const message = String(error?.message || error || 'send_failed').slice(0, 1200);
    const failureKind = /Bad MAC|MessageCounterError|No sessions|SessionError|decrypt|encrypt|pre.?key|signal/i.test(message)
        ? 'session_signal_failure'
        : /invalid.*jid|not.*found|recipient|user.*not.*found|404|400/i.test(message)
            ? 'recipient_or_message_failure'
            : /timeout|timed out|socket|closed|connection|network|econn|enotfound|etimedout/i.test(message)
                ? 'session_transport_failure'
                : 'session_send_failure';
    const now = new Date();
    if (db && sessionId) {
        await db.collection('session_owners').updateOne(
            { sessionId, ownerInstanceId: TFBOT_CLUSTER_INSTANCE_ID },
            { $set: { lastSendFailureAt: now, lastSendFailureKind: failureKind, lastSendFailureHash: shortLogHash(message), updatedAt: now } }
        ).catch(databaseError => console.warn('[session-send-failure-record-failed]', { sessionId, error: databaseError?.message || String(databaseError) }));
    }
    console.warn('[whatsapp-session-send-failure]', {
        sessionId,
        host: TFBOT_CLUSTER_INSTANCE_HOST,
        generation: tfbotWorkerSelectionGeneration || null,
        failureKind,
        errorHash: shortLogHash(message),
        infrastructureFailover: false,
        action: 'keep_current_worker_and_handle_failure_for_this_session_only'
    });
    return false;
}

function getWhatsAppDestinationType(jid) {
    const value = String(jid || '').trim();
    if (value === 'status@broadcast') return 'status';
    if (/@g\.us$/i.test(value)) return 'group';
    if (/@newsletter$/i.test(value)) return 'channel';
    if (/@(?:hosted\.)?lid$/i.test(value)) return 'private_lid';
    if (/@s\.whatsapp\.net$/i.test(value)) return 'private_pn';
    return value ? 'other' : 'unknown';
}

function getOutgoingDiagnosticText(content) {
    const source = content?.message && typeof content.message === 'object' ? content.message : content || {};
    const candidates = [
        source?.text,
        source?.caption,
        source?.conversation,
        source?.extendedTextMessage?.text,
        source?.imageMessage?.caption,
        source?.videoMessage?.caption,
        source?.documentMessage?.caption,
        source?.documentWithCaptionMessage?.message?.documentMessage?.caption,
        source?.templateMessage?.hydratedTemplate?.hydratedContentText,
        source?.buttonsMessage?.contentText,
        source?.listMessage?.description
    ];
    const selected = candidates.find(value => typeof value === 'string' && value.trim());
    return selected ? String(selected).replace(/\u0000/g, '').slice(0, 1500) : '';
}

function classifyWhatsAppFailure(error) {
    const value = getSignalLogText([error]);
    if (/Bad MAC|SignalErrorBadMac|SignalErrorInvalidMessage|calculateMAC/i.test(value)) return 'bad_mac';
    if (/Chain closed|Decrypted message with closed session|closed session/i.test(value)) return 'chain_closed';
    if (/MessageCounterError|Key used already or never filled/i.test(value)) return 'message_counter_error';
    if (/SessionError:\s*No sessions|No sessions|No session found to decrypt message/i.test(value)) return 'signal_session_missing';
    if (/pre.?key|identity.?key|signed.?pre.?key/i.test(value)) return 'signal_key_state';
    if (/timeout|timed out|ETIMEDOUT/i.test(value)) return 'timeout';
    if (/socket|connection|ECONN|EPIPE|closed/i.test(value)) return 'transport';
    return 'other';
}

function shouldActivateLegacyMessagingFallback(error) {
    const failureClass = classifyWhatsAppFailure(error);
    return ['bad_mac', 'chain_closed', 'message_counter_error', 'signal_session_missing', 'signal_key_state'].includes(failureClass)
        || /Failed to decrypt message|failed to decrypt message|SignalErrorInvalidMessage|calculateMAC|retry.{0,20}(?:error|code).{0,8}(?:4|7)\b/i.test(getSignalLogText([error]));
}

