async function addDel2Target(sessionId, gjid, targetJid) {
    try {
        const col = db.collection('group_del2');
        await col.updateOne({ sessionId, gjid, targetJid }, { $set: { active: true } }, { upsert: true });
        activeDel2UsersCache.delete(`${sessionId}_${gjid}`);
        const current = await getDel2Targets(sessionId, gjid);
        if (!current.includes(targetJid)) {
            current.push(targetJid);
            setBoundedMapEntry(activeDel2UsersCache, `${sessionId}_${gjid}`, current, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
        }
    } catch (error) {
        console.error('[del2-target-add-failed]', { sessionId, group: gjid, target: targetJid, error: error?.message || String(error) });
        throw error;
    }
}

async function removeDel2Target(sessionId, gjid, targetJid) {
    try {
        const col = db.collection('group_del2');
        await col.deleteMany({ sessionId, gjid, targetJid });
        activeDel2UsersCache.delete(`${sessionId}_${gjid}`);
        const current = await getDel2Targets(sessionId, gjid);
        const index = current.indexOf(targetJid);
        if (index > -1) {
            current.splice(index, 1);
            setBoundedMapEntry(activeDel2UsersCache, `${sessionId}_${gjid}`, current, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
        }
    } catch (error) {
        console.error('[del2-target-remove-failed]', { sessionId, group: gjid, target: targetJid, error: error?.message || String(error) });
        throw error;
    }
}

function getWhatsAppMessageFormat(value) {
    const source = value?.message && typeof value.message === 'object' ? value.message : value;
    const groups = {
        text: ['conversation', 'extendedTextMessage', 'buttonsResponseMessage', 'listResponseMessage', 'templateButtonReplyMessage', 'interactiveResponseMessage', 'groupMentionMessage', 'buttonsMessage', 'listMessage', 'templateMessage', 'interactiveMessage'],
        image: ['imageMessage'],
        video: ['videoMessage', 'ptvMessage'],
        audio: ['audioMessage', 'voiceMessage'],
        document: ['documentMessage'],
        sticker: ['stickerMessage', 'lottieStickerMessage'],
        album: ['albumMessage'],
        location: ['locationMessage', 'liveLocationMessage'],
        contact: ['contactMessage', 'contactsArrayMessage', 'phoneNumberShareMessage'],
        poll: ['pollCreationMessage', 'pollCreationMessageV2', 'pollCreationMessageV3', 'pollUpdateMessage'],
        reaction: ['reactionMessage'],
        event: ['eventMessage', 'scheduledCallCreationMessage', 'scheduledCallEditMessage'],
        status: ['groupStatusMessageContent', 'groupStatusMessage', 'groupStatusMessageV2', 'statusMessage', 'statusMentionMessage', 'statusMentionMessageV2', 'statusMentionMessageV2Extension', 'statusMentionMessageExtension'],
        group: ['groupInviteMessage', 'newsletterAdminInviteMessage'],
        commerce: ['productMessage', 'orderMessage', 'catalogMessage'],
        payment: ['paymentInviteMessage', 'requestPaymentMessage', 'sendPaymentMessage', 'declinePaymentRequestMessage', 'cancelPaymentRequestMessage'],
        call: ['callLogMessage']
    };
    const keyToFormat = new Map();
    for (const [format, keys] of Object.entries(groups)) for (const key of keys) keyToFormat.set(key, format);
    const mediaFormats = new Set(['image', 'video', 'audio', 'document', 'sticker', 'album']);
    const ignored = new Set(['messageContextInfo', 'senderKeyDistributionMessage', 'protocolMessage', 'keepInChatMessage', 'messageHistoryBundle', 'contextInfo', 'quotedMessage', 'deviceListMetadata', 'deviceListMetadataVersion', 'messageSecret', 'externalAdReply', 'thumbnail', 'jpegThumbnail']);
    const wrapperKeys = new Set(['ephemeralMessage', 'viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension', 'documentWithCaptionMessage', 'deviceSentMessage', 'editedMessage', 'associatedChildMessage', 'groupStatusMessageContent', 'statusMessage']);
    const viewOnceWrapperKeys = new Set(['viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension']);
    const getNested = payload => {
        if (!payload || typeof payload !== 'object') return null;
        if (payload.message && typeof payload.message === 'object') return payload.message;
        if (payload.content && typeof payload.content === 'object') return payload.content;
        if (payload.associatedChildMessage && typeof payload.associatedChildMessage === 'object') return payload.associatedChildMessage;
        return payload;
    };
    const scan = (node, depth, seen, inheritedViewOnce = false) => {
        if (!node || typeof node !== 'object' || depth > 18 || seen.has(node)) return '';
        seen.add(node);
        const entries = Object.entries(node);
        const nodeViewOnce = inheritedViewOnce || node.viewOnce === true || node.isViewOnce === true || node.is_view_once === true;
        for (const [key] of entries) {
            if (ignored.has(key)) continue;
            const known = keyToFormat.get(key);
            if (known === 'status') return 'status';
        }
        for (const [key, payload] of entries) {
            if (!viewOnceWrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const found = scan(getNested(payload), depth + 1, seen, true);
            if (found) return found;
        }
        for (const [key, payload] of entries) {
            if (!wrapperKeys.has(key) || viewOnceWrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const found = scan(getNested(payload), depth + 1, seen, nodeViewOnce);
            if (found) return found;
        }
        for (const [key, payload] of entries) {
            if (ignored.has(key) || wrapperKeys.has(key)) continue;
            const known = keyToFormat.get(key);
            if (!known) continue;
            const payloadViewOnce = payload && typeof payload === 'object' && (payload.viewOnce === true || payload.isViewOnce === true || payload.is_view_once === true);
            return known;
        }
        let fallback = '';
        for (const [key, payload] of entries) {
            if (ignored.has(key) || wrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const found = scan(payload, depth + 1, seen, nodeViewOnce);
            if (found && !found.startsWith('other:')) return found;
            if (found && !fallback) fallback = found;
            if (!found && !fallback) fallback = `other:${String(key).slice(0, 80)}`;
        }
        return fallback;
    };
    return scan(source, 0, new WeakSet());
}

function extractWhatsAppResendMedia(value) {
    const source = value?.message && typeof value.message === 'object' ? value.message : value;
    const wrapperKeys = new Set([
        'ephemeralMessage', 'viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension',
        'documentWithCaptionMessage', 'deviceSentMessage', 'editedMessage', 'associatedChildMessage',
        'groupStatusMessageContent', 'groupStatusMessage', 'groupStatusMessageV2', 'statusMessage',
        'statusMentionMessage', 'statusMentionMessageV2', 'statusMentionMessageV2Extension', 'statusMentionMessageExtension'
    ]);
    const viewOnceWrapperKeys = new Set(['viewOnceMessage', 'viewOnceMessageV2', 'viewOnceMessageV2Extension']);
    const ignoredKeys = new Set([
        'messageContextInfo', 'contextInfo', 'quotedMessage', 'senderKeyDistributionMessage',
        'protocolMessage', 'messageSecret', 'deviceListMetadata', 'deviceListMetadataVersion',
        'externalAdReply', 'thumbnail', 'jpegThumbnail'
    ]);
    const mediaTypes = {
        imageMessage: { type: 'image', downloadType: 'image', sendType: 'image' },
        videoMessage: { type: 'video', downloadType: 'video', sendType: 'video' },
        ptvMessage: { type: 'video', downloadType: 'video', sendType: 'video' },
        audioMessage: { type: 'audio', downloadType: 'audio', sendType: 'audio' },
        voiceMessage: { type: 'audio', downloadType: 'audio', sendType: 'audio', ptt: true },
        documentMessage: { type: 'document', downloadType: 'document', sendType: 'document' },
        stickerMessage: { type: 'sticker', downloadType: 'sticker', sendType: 'sticker' },
        lottieStickerMessage: { type: 'sticker', downloadType: 'sticker', sendType: 'sticker' }
    };
    const visit = (node, inheritedViewOnce, depth, seen) => {
        if (!node || typeof node !== 'object' || depth > 20 || seen.has(node)) return null;
        seen.add(node);
        const nodeViewOnce = inheritedViewOnce || node.viewOnce === true || node.isViewOnce === true || node.is_view_once === true;
        const entries = Object.entries(node);
        for (const [key, payload] of entries) {
            if (!wrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const nested = payload.message && typeof payload.message === 'object'
                ? payload.message
                : payload.content && typeof payload.content === 'object'
                    ? payload.content
                    : payload;
            const result = visit(nested, nodeViewOnce || viewOnceWrapperKeys.has(key), depth + 1, seen);
            if (result) return result;
        }
        for (const [key, payload] of entries) {
            const descriptor = mediaTypes[key];
            if (!descriptor || !payload || typeof payload !== 'object') continue;
            return {
                ...descriptor,
                payload,
                viewOnce: nodeViewOnce || payload.viewOnce === true || payload.isViewOnce === true || payload.is_view_once === true,
                sourceType: key
            };
        }
        for (const [key, payload] of entries) {
            if (ignoredKeys.has(key) || wrapperKeys.has(key) || !payload || typeof payload !== 'object') continue;
            const result = visit(payload, nodeViewOnce, depth + 1, seen);
            if (result) return result;
        }
        return null;
    };
    return visit(source, false, 0, new WeakSet());
}
async function findQuotedMessageForCommand(sessionId, chatJid, messageId, allowOutgoingLegacy = true) {
    const id = String(messageId || '').trim();
    const chat = String(chatJid || '').trim();
    if (!sessionId || !id) return null;
    const inMemory = recentMsgsCache.find(entry => {
        if (entry.sessionId !== sessionId || String(entry.id) !== id) return false;
        const aliases = [entry.from, ...(Array.isArray(entry.chatAliases) ? entry.chatAliases : []), entry.key?.remoteJidAlt].filter(Boolean);
        return !chat || aliases.some(alias => String(alias) === chat || areEquivalentWhatsAppChatJids(sessionId, alias, chat));
    });
    if (inMemory?.message) return { ...inMemory, source: 'session_memory' };
    if (!db) return null;
    try {
        const quoted = await db.collection('baileys_quoted_messages').findOne(
            { _id: `quoted:${sessionId}:${id}`, sessionId, messageId: id },
            { projection: { sessionId: 1, messageId: 1, remoteJid: 1, remoteJidAlt: 1, remoteJidAliases: 1, fromMe: 1, participant: 1, participantAlt: 1, participantPn: 1, senderPn: 1, key: 1, message: 1, messageFormat: 1, messageTimestamp: 1 } }
        );
        if (quoted && (quoted.message || quoted.messageFormat)) {
            const aliases = [quoted.remoteJid, quoted.remoteJidAlt, ...(Array.isArray(quoted.remoteJidAliases) ? quoted.remoteJidAliases : [])].filter(Boolean);
            if (!chat || aliases.some(alias => String(alias) === chat || areEquivalentWhatsAppChatJids(sessionId, alias, chat))) return { ...quoted, source: 'persistent_quoted_cache' };
        }
    } catch (error) {
        console.warn('[quoted-message-cache-read-failed]', { sessionId, messageId: id, error: error?.message || String(error) });
    }
    if (!allowOutgoingLegacy) return null;
    try {
        const legacy = await db.collection('baileys_outgoing_messages').findOne(
            { _id: `${sessionId}:${id}`, sessionId, messageId: id },
            { projection: { sessionId: 1, messageId: 1, remoteJid: 1, remoteJidAlt: 1, remoteJidAliases: 1, fromMe: 1, participant: 1, participantAlt: 1, participantPn: 1, senderPn: 1, message: 1, messageTimestamp: 1 } }
        );
        if (legacy?.message) {
            const aliases = [legacy.remoteJid, legacy.remoteJidAlt, ...(Array.isArray(legacy.remoteJidAliases) ? legacy.remoteJidAliases : [])].filter(Boolean);
            if (!chat || !aliases.length || aliases.some(alias => String(alias) === chat || areEquivalentWhatsAppChatJids(sessionId, alias, chat))) return { ...legacy, source: 'legacy_outgoing_cache' };
        }
    } catch (error) {
        console.warn('[quoted-message-legacy-read-failed]', { sessionId, messageId: id, error: error?.message || String(error) });
    }
    return null;
}

async function getDel3Rules(sessionId, gjid) {
    const cacheKey = `${sessionId}_${gjid}`;
    if (activeDel3RulesCache.has(cacheKey)) return activeDel3RulesCache.get(cacheKey);
    if (!db) return [];
    const docs = await db.collection('group_del3').find({ sessionId, gjid, active: true }).toArray();
    const rules = docs.map(doc => ({ format: String(doc.messageFormat || '').trim(), sampleText: doc.sampleText || '', activatedAt: doc.activatedAt || doc.updatedAt || doc.createdAt || null })).filter(rule => rule.format);
    setBoundedMapEntry(activeDel3RulesCache, cacheKey, rules, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
    return rules;
}

async function stageDel3Rule(sessionId, gjid, messageFormat, sampleText) {
    if (!db) throw new Error('del3_database_unavailable');
    const now = new Date();
    await db.collection('group_del3').updateOne(
        { sessionId, gjid, messageFormat },
        { $set: { active: false, activationPending: true, sampleText: String(sampleText || '').slice(0, 500), pendingAt: now, updatedAt: now }, $setOnInsert: { createdAt: now } },
        { upsert: true }
    );
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
    return now;
}

async function activateDel3Rule(sessionId, gjid, messageFormat) {
    if (!db) throw new Error('del3_database_unavailable');
    const activatedAt = new Date();
    const result = await db.collection('group_del3').updateOne(
        { sessionId, gjid, messageFormat, activationPending: true },
        { $set: { active: true, activatedAt, updatedAt: activatedAt }, $unset: { activationPending: '', pendingAt: '' } }
    );
    if (!result || Number(result.matchedCount || 0) !== 1) throw new Error('del3_pending_rule_not_found');
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
    const docs = await db.collection('group_del3').find({ sessionId, gjid, active: true }).toArray();
    const rules = docs.map(doc => ({ format: String(doc.messageFormat || '').trim(), sampleText: doc.sampleText || '', activatedAt: doc.activatedAt || doc.updatedAt || doc.createdAt || null })).filter(rule => rule.format);
    setBoundedMapEntry(activeDel3RulesCache, `${sessionId}_${gjid}`, rules, ACTIVE_DEL2_CACHE_MAX_ENTRIES);
    return activatedAt;
}

async function discardPendingDel3Rule(sessionId, gjid, messageFormat) {
    if (db) await db.collection('group_del3').deleteMany({ sessionId, gjid, messageFormat, activationPending: true });
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
}

async function removeDel3Rule(sessionId, gjid, messageFormat) {
    if (db) await db.collection('group_del3').deleteMany({ sessionId, gjid, messageFormat });
    activeDel3RulesCache.delete(`${sessionId}_${gjid}`);
    return getDel3Rules(sessionId, gjid);
}

async function resolveDel3ParticipantIdentity(sock, sessionId, groupJid, identityValues) {
    const aliases = [...new Set((Array.isArray(identityValues) ? identityValues : [identityValues]).map(value => String(value || '').trim()).filter(Boolean))];
    const unresolvedLids = [];
    for (const value of [...aliases]) {
        const lid = normalizeLidCacheKey(value);
        if (!/@lid$/i.test(lid)) continue;
        let phone = normalizePhoneCacheJid(getRememberedPhoneForLid(sessionId, lid));
        if (!phone) phone = normalizePhoneCacheJid(phoneFromCachedGroupMetadata(sessionId, lid)?.phone || '');
        if (!phone && typeof sock?.signalRepository?.lidMapping?.getPNForLID === 'function') {
            try {
                phone = normalizePhoneCacheJid(await promiseWithTimeout(sock.signalRepository.lidMapping.getPNForLID(lid), 1800, 'Del3 participant PN lookup'));
                if (phone) rememberLidPhonePair(sessionId, lid, phone, 'signal_lid_mapping');
            } catch (error) {
                console.warn('[del3-lid-identity-resolution-failed]', { sessionId, group: groupJid, identityHash: shortLogHash(lid), error: error?.message || String(error) });
            }
        }
        if (phone) aliases.push(phone);
        else unresolvedLids.push(lid);
    }
    return { aliases: [...new Set(aliases)], unresolvedLids: [...new Set(unresolvedLids)], hasPhoneIdentity: aliases.some(value => !!normalizePhoneCacheJid(value)) };
}

async function applyDel3ToIncomingMessage(sock, sessionId, message, groupJid, senderJid, senderAliases, ownerRecord, canBotModerateGroupFn, isProtectedWhatsAppTargetFn) {
    const chat = String(groupJid || message?.key?.remoteJid || '').trim();
    const messageId = String(message?.key?.id || '').trim();
    if (!/@g\.us$/i.test(chat) || !messageId || message?.key?.fromMe === true) return false;
    const format = getWhatsAppMessageFormat(message);
    if (!format) return false;
    const rules = await getDel3Rules(sessionId, chat);
    const matchingRule = rules.find(rule => rule.format === format);
    if (!matchingRule) return false;
    if (typeof canBotModerateGroupFn === 'function' && !await canBotModerateGroupFn(chat)) {
        console.warn('[del3-skip-bot-permission-unavailable]', { sessionId, group: chat, messageId, format });
        return false;
    }
    const ownerIdentityAvailable = !!(ownerRecord && typeof ownerRecord === 'object' && [ownerRecord.Number, ownerRecord.number, ownerRecord.OwnerNumber, ownerRecord.ownerNumber, ownerRecord.PairingNumber, ownerRecord.AccountJid, ownerRecord.accountJid, ownerRecord.OwnerLid, ownerRecord.ownerLid].some(value => String(value || '').trim()));
    if (!ownerIdentityAvailable) {
        console.warn('[del3-message-protected]', { sessionId, group: chat, messageId, format, reason: 'owner_identity_record_unavailable_fail_closed' });
        return false;
    }
    const sourceKey = message?.key || {};
    const senderIdentityResolution = await resolveDel3ParticipantIdentity(sock, sessionId, chat, [senderJid, ...(Array.isArray(senderAliases) ? senderAliases : []), sourceKey.participant, sourceKey.participantAlt, sourceKey.participantPn, sourceKey.senderPn]);
    const aliasText = senderIdentityResolution.aliases.join(' ');
    const senderIsProtected = typeof isProtectedWhatsAppTargetFn === 'function' && isProtectedWhatsAppTargetFn(senderJid, ownerRecord, sock?.user?.id || '', aliasText);
    if (senderIsProtected) {
        console.info('[del3-message-protected]', { sessionId, group: chat, messageId, format, reason: 'host_or_bot' });
        return false;
    }
    if (senderIdentityResolution.unresolvedLids.length && !senderIdentityResolution.hasPhoneIdentity) {
        console.warn('[del3-message-protected]', { sessionId, group: chat, messageId, format, reason: 'unresolved_lid_identity_fail_closed', unresolvedLidCount: senderIdentityResolution.unresolvedLids.length });
        return false;
    }
    const timestampRaw = message?.messageTimestamp && typeof message.messageTimestamp.toNumber === 'function' ? message.messageTimestamp.toNumber() : message?.messageTimestamp;
    const timestamp = Number(timestampRaw) || 0;
    const messageTimestampMs = timestamp > 0 ? (timestamp < 1000000000000 ? timestamp * 1000 : timestamp) : 0;
    const activatedAtMs = matchingRule.activatedAt ? new Date(matchingRule.activatedAt).getTime() : 0;
    if (messageTimestampMs > 0 && activatedAtMs > 0 && messageTimestampMs < activatedAtMs - 5000) {
        console.info('[del3-message-skipped-before-activation]', { sessionId, group: chat, messageId, format, messageTimestampMs, activatedAtMs });
        return false;
    }
    console.info('[del3-live-delete-validation]', { sessionId, group: chat, messageId, format, action: 'attempt_delete_and_use_whatsapp_server_ack_as_authority' });
    const account = getAuthenticatedPhoneNumber(sock?.user, activeSessions.get(sessionId)?.authState?.creds) || getAuthenticatedLid(sock?.user, activeSessions.get(sessionId)?.authState?.creds) || sessionId;
    const dedupId = `del3:${shortLogHash(account)}:${chat}:${messageId}`;
    if (del3DeleteDedupCache.has(dedupId)) return false;
    let claimed = false;
    try {
        if (db) {
            const claim = await db.collection('processed_messages').updateOne(
                { _id: dedupId },
                { $setOnInsert: { sessionId, messageId, remoteJid: chat, operation: 'del3', ts: Date.now(), expireAt: new Date(Date.now() + PROCESSED_MESSAGE_RETENTION_MS) } },
                { upsert: true }
            );
            claimed = claim.upsertedCount === 1;
            if (!claimed) return false;
        } else claimed = true;
        del3DeleteDedupCache.set(dedupId, Date.now());
        while (del3DeleteDedupCache.size > 12000) del3DeleteDedupCache.delete(del3DeleteDedupCache.keys().next().value);
        const sourceKey = message.key || {};
        const participant = String(sourceKey.participant || sourceKey.participantPn || sourceKey.participantAlt || sourceKey.senderPn || senderJid || '').trim();
        const deleteKey = { ...sourceKey, remoteJid: String(sourceKey.remoteJid || chat), id: messageId, fromMe: sourceKey.fromMe === true };
        if (participant) deleteKey.participant = participant;
        const deleteResult = await queuedDeleteMessageWithAck(sock, chat, deleteKey, 180, 6500);
        console.info('[del3-message-format-matched]', { sessionId, group: chat, messageId, format, deleteRequestSent: true, serverAcknowledgementTracked: true, serverAcknowledged: true, acknowledgementStatus: deleteResult.acknowledgementStatus, scope: 'same_group_same_whatsapp_format' });
        return true;
    } catch (error) {
        if (claimed && db) await db.collection('processed_messages').deleteOne({ _id: dedupId }).catch(() => {});
        del3DeleteDedupCache.delete(dedupId);
        console.warn('[del3-message-delete-failed]', { sessionId, group: chat, messageId, format, error: error?.message || String(error) });
        return false;
    }
}

process.on('unhandledRejection', (error) => {
    const message = String(error?.message || error || '');
    const expectedClosedSocket = /^(?:Connection Closed|1006)$|WebSocket is not open|socket.*closed/i.test(message);
    if (expectedClosedSocket && (tfbotWorkerStopping || serverShuttingDown || workerDrainingSessionIds.size > 0 || Date.now() < workerDrainExpectedClosedUntil)) {
        console.warn('[baileys-closed-socket-rejection-during-handoff]', { error: message.slice(0, 120), workerStopping: tfbotWorkerStopping, drainingSessionCount: workerDrainingSessionIds.size, action: 'expected_transport_close_while_worker_handoff' });
        return;
    }
    if (expectedClosedSocket) {
        console.warn('[baileys-closed-socket-rejection]', { error: message.slice(0, 120), action: 'socket_closed_without_process_crash' });
        return;
    }
    console.error('[unhandledRejection]', error?.message || error);
});
process.on('uncaughtException', (error) => {
    const exceptionText = String(error?.message || error?.stack || error || 'unknown');
    if (/Failed to decrypt message with any known session|Bad MAC/i.test(exceptionText)) {
        console.warn('[whatsapp-signal] An individual message could not be decrypted; the bot remains online and stored auth data is preserved.');
        return;
    }
    console.error('[uncaughtException]', error?.stack || error?.message || error);
    process.exit(1);
});

