            sock: sock,
            socketCreatedAt: existingSessionRecord?.sock === sock ? Number(existingSessionRecord?.socketCreatedAt || pairingSnapshotAtBootstrap?.socketCreatedAt || Date.now()) : Date.now(),
            authState: state,
